DECKS.push({ id: 'phys-m8-bb', fa: 'fa1', title: 'Big Bang and the formation of matter', dps: ['8.1.1'], cards: [
  { id: 'p8bb02', dp: '8.1.1', t: 'con', q: 'What does the Big Bang theory propose about the early Universe?', a: L(['Space expanded from a <b>hot, dense initial state</b>.', 'Early inflation rapidly expanded space; subsequent cooling allowed more complex matter to form.']) + N('Source: an explosion from a proven singularity. Correct: expansion of space; the singularity is an extrapolation.') },
  { id: 'p8bb04', dp: '8.1.1', t: 'con', q: 'How did pair production transform radiation into matter?', a: L(['High-energy radiation produced <b>particle–antiparticle pairs</b>.', 'Radiation energy became rest mass and kinetic energy.']) + E('E = Δmc^2') },
  { id: 'p8bb05', dp: '8.1.1', t: 'con', q: 'What happens in particle–antiparticle annihilation?', a: L(['A particle and its antiparticle convert rest mass into <b>radiation</b>.', 'Electron–positron annihilation produces gamma photons.']) },
  { id: 'p8bb06', dp: '8.1.1', t: 'con', q: 'Why did cooling allow quarks to form protons and neutrons?', a: L(['Cooling reduced particle <b>kinetic energy</b>.', 'Quarks could remain bound in <b>hadrons</b>, including protons and neutrons.']) },
  { id: 'p8bb07', dp: '8.1.1', t: 'con', q: 'What formed during Big Bang nucleosynthesis?', a: L(['Within minutes, protons and neutrons formed <b>light nuclei</b>: deuterium, helium and traces of lithium.', 'Neutral atoms formed much later.']) + N('Source confuses nuclei with atoms and excludes primordial helium. Light nuclei formed before neutral atoms.') },
  { id: 'p8bb08', dp: '8.1.1', t: 'con', q: 'How are recombination and decoupling related?', a: L(['<b>Recombination:</b> electrons bound to nuclei to form neutral atoms.', '<b>Decoupling:</b> photons then travelled relatively freely.', 'That radiation is observed as the <b>cosmic microwave background</b>.']) + N('The booklet’s 300 000-year timing is approximate.') },
  { id: 'p8bb09', dp: '8.1.1', t: 'con', q: 'How did uneven matter density lead to galaxies and stars?', a: L(['Denser regions attracted gas through <b>gravity</b>.', 'Collapsing clouds formed galaxies and protostars.', 'Compression heated stellar cores until fusion could begin.']) + N('Annihilation patches are not established as the cause of density variations.') },
]});
DECKS.push({ id: 'phys-m8-he', fa: 'fa1', title: 'Evidence for expansion and Hubble’s law', dps: ['8.1.2'], cards: [
  { id: 'p8he01', dp: '8.1.2', t: 'rec', q: 'What three main observations support the Big Bang theory in the booklet?', a: L(['<b>Hubble’s law:</b> galaxy recession speed increases with distance.', '<b>Primordial abundance:</b> about 75% hydrogen and 25% helium by mass.', '<b>CMB:</b> nearly uniform background with a 2.7 K black body spectrum.']) },
  { id: 'p8he02', dp: '8.1.2', t: 'con', q: 'How does a 7:1 proton-to-neutron ratio produce a 3:1 hydrogen-to-helium mass ratio?', a: OL(['Take 14 protons and 2 neutrons.', 'Use 2 protons and 2 neutrons to make one helium-4 nucleus; 12 protons remain as hydrogen nuclei.', 'Hydrogen:helium mass ≈ 12:4 = <b>3:1</b>; number ratio = <b>12:1</b>.']) + N('Source: 3:1 by number. Correct: 3:1 by mass; about 12:1 by number.') },
  { id: 'p8he03', dp: '8.1.2', t: 'con', q: 'Why is the cosmic microwave background evidence for a hot early Universe?', a: L(['A hot early Universe should leave <b>thermal radiation</b>.', 'Expansion stretched its wavelengths and cooled it.', 'Penzias and Wilson detected the background; its measured 2.7 K spectrum supports this prediction.']) },
  { id: 'p8he04', dp: '8.1.2', t: 'con', q: 'How did Leavitt’s Cepheid work help Hubble measure galaxy distances?', a: L(['Cepheid <b>period gives intrinsic luminosity</b>.', 'Compare intrinsic luminosity with apparent brightness to calculate distance.', 'Cepheids therefore allowed galaxy distances to be measured.']) + N('Apparent brightness alone is insufficient; period gives intrinsic luminosity.') },
  { id: 'p8he05', dp: '8.1.2', t: 'con', q: 'What information did Slipher obtain from galaxy spectra?', a: L(['Compare galaxy lines with <b>laboratory wavelengths</b>.', 'Redshift indicates recession; shift magnitude gives recession speed.']) + N('Source: all galaxies recede. Correct: nearly all distant galaxies; some nearby galaxies approach.') },
  { id: 'p8he06', dp: '8.1.2', t: 'eq', q: 'What is Hubble’s law and what does its gradient represent?', a: E('v = H_0D') + L(['v: recession speed in <b>km s^{-1}</b>; D: distance in <b>Mpc</b>.', 'The v–D graph is linear; its gradient is H_0 in km s^{-1} Mpc^{-1}.']) },
  { id: 'p8he07', dp: '8.1.2', t: 'prac', q: 'How should the booklet’s galaxy data be used to estimate H_0?', a: OL(['Plot <b>D / Mpc</b> horizontally and <b>v / km s^{-1}</b> vertically.', 'Draw a straight best-fit line through the origin.', 'Use widely separated fitted points: H_0 = Δv/ΔD.']) + N('Best-fit gradients vary. The key mixes 66, 13 000/196, 72.1 and 67.2; keep one gradient consistently.') },
  { id: 'p8he08', dp: '8.1.2', t: 'calc', q: 'Using H_0 = 72.1 km s^{-1} Mpc^{-1} and 1 Mpc = 3.086 × 10^{22} m, estimate the Hubble time.', a: OL(['H_0 = 72 100 ÷ (3.086 × 10^{22}) = 2.33636 × 10^{-18} s^{-1}.', 't = 1/H_0 = 4.28017 × 10^{17} s.', 't = (4.28017 × 10^{17}) ÷ (365.25 × 24 × 3600) = <b>1.36 × 10^{10} years</b>.']) + N('Source: 13.5 billion years. Correct rounding: 13.6 billion. Reciprocal H_0 is an approximate Hubble time.') },
  { id: 'p8he10', dp: '8.1.2', t: 'exam', q: '2019 HSC (1 mark; Q8): Which reproduced graph matches Hubble’s measurements: A, straight v–D graph in km s^{-1} and 10^6 pc; B, straight graph in km s^{-1} and 10^6 light years; C and D, upward-curving versions?', a: L(['<b>A</b> is the booklet’s keyed answer: recession speed is directly proportional to distance, with its stated measurement units.']) + N('The key gives A. Changing distance units alone does not invalidate a linear law; the supplied explanation is incomplete.') },
  { id: 'p8he11', dp: '8.1.2', t: 'con', q: 'How do distant young-looking galaxies support an evolving Universe?', a: L(['Distant light shows galaxies at <b>earlier times</b>.', 'More distant radio galaxies and short-lived blue stars indicate an evolving Universe.']) },
]});
DECKS.push({ id: 'phys-m8-em', fa: 'fa1', title: 'Mass-energy equivalence in stellar calculations', dps: ['8.1.3'], cards: [
  { id: 'p8em01', dp: '8.1.3', t: 'calc', q: 'Using the booklet’s PP I values 1.44, 5.49 and 12.86 MeV, what energy is released per complete chain?', a: OL(['The first two steps occur twice: E = 2(1.44 + 5.49) + 12.86.', 'E = <b>26.72 MeV</b>.', 'E = 26.72 × 10^6 × 1.602 × 10^{-19} = <b>4.281 × 10^{-12} J</b>.']) + N('1.44 MeV includes annihilation. The listed rounded steps give 26.72, rather than 26.73 MeV.') },
  { id: 'p8em02', dp: '8.1.3', t: 'calc', q: 'At the worksheet luminosity 4 × 10^{26} W, how many complete PP I chains occur per second?', a: OL(['Use unrounded E = 4.280544 × 10^{-12} J per chain.', 'Rate = luminosity/E = (4 × 10^{26}) ÷ (4.280544 × 10^{-12}).', 'Rate ≈ <b>9 × 10^{37} chains s^{-1}</b> to the one significant figure supplied for luminosity.']) + N('Unrounded rate: 9.34461 × 10^{37} s^{-1}; input luminosity limits precision.') },
  { id: 'p8em03', dp: '8.1.3', t: 'calc', q: 'At 4 × 10^{26} W, what rest mass does the Sun convert to energy each second and each 365-day year?', a: OL(['E = Δmc^2, so mass-conversion rate = L/c^2.', 'Rate = (4 × 10^{26})/(3.00 × 10^8)^2 = 4.44444 × 10^9 kg s^{-1}.', 'Annual amount = (4.44444 × 10^9)(365 × 24 × 3600) = 1.4016 × 10^{17} kg.', 'To the supplied luminosity precision: <b>4 × 10^9 kg s^{-1}</b> and <b>1 × 10^{17} kg per year</b>.']) },
  { id: 'p8em04', dp: '8.1.3', t: 'calc', q: 'Using constant luminosity 4 × 10^{26} W and solar mass 2 × 10^{30} kg, what fraction of the Sun’s mass converts to energy in 5 billion years?', a: OL(['Use annual mass conversion 1.4016 × 10^{17} kg.', 'Converted mass = (1.4016 × 10^{17})(5 × 10^9) = 7.008 × 10^{26} kg.', 'Percentage = [(7.008 × 10^{26})/(2 × 10^{30})] × 100 = 0.03504%.', 'At the input precision this is <b>0.04%</b>.']) + N('The Sun will become a red giant, not undergo the worksheet’s nova. Constant luminosity is a calculation assumption.') },
  { id: 'p8em05', dp: '8.1.3', t: 'calc', q: 'Using the CNO worksheet’s step energies 1.95, 1.20, 7.54, 7.35, 1.73 and 4.96 MeV, calculate the listed total energy.', a: OL(['E = 1.95 + 1.20 + 7.54 + 7.35 + 1.73 + 4.96 = <b>24.73 MeV</b>.', 'E = 24.73 × 10^6 × 1.602 × 10^{-19} = <b>3.962 × 10^{-12} J</b>.']) + N('24.73 MeV sums the listed values; it is not identical to the quoted overall 26.7 MeV including annihilation.') },
  { id: 'p8em07', dp: '8.1.3', t: 'exam', q: '2019 NESA sample (7 marks; Q12): Justify calling E = mc^2 one of the most important equations in physics.', a: L(['It connects <b>rest mass and energy</b>, allowing quantitative predictions across several fields.', 'In fusion and fission, lower product rest mass explains the released energy and enables nuclear-energy calculations.', 'It links a nucleus’s <b>mass defect to binding energy</b>.', 'It accounts for energy carried by radioactive-decay products.', 'It explains stellar energy production and underpins nuclear-reactor applications.', 'In high-energy collisions, energy can produce new particles, helping test models of matter.']) },
]});
DECKS.push({ id: 'phys-m8-sp', fa: 'fa1', title: 'Producing and observing spectra', dps: ['8.1.4', '7.1.4', '7.1.5'], cards: [
  { id: 'p8sp01', dp: '8.1.4', t: 'def', q: 'What produces a continuous spectrum?', a: L(['A <b>hot solid, liquid or dense gas</b> produces radiation over a continuous range of wavelengths.', 'Its intensity varies with wavelength; a black body is an ideal absorber and thermal emitter.']) },
  { id: 'p8sp02', dp: '8.1.4', t: 'con', q: 'How does a hot low-pressure gas produce an emission-line spectrum?', a: L(['Energy excites gas electrons.', 'Downward transitions emit photons with <b>E = hf = hc/λ</b>.', 'Discrete energy gaps produce bright lines on a dark background.']) },
  { id: 'p8sp03', dp: '8.1.4', t: 'con', q: 'How does a cooler gas produce an absorption-line spectrum?', a: L(['Continuous light passes through <b>cooler gas</b>.', 'Atoms absorb photons matching allowed energy gaps.', 'Re-emission in other directions leaves dark lines in the transmitted continuum.']) },
  { id: 'p8sp05', dp: '7.1.4', t: 'prac', q: 'How can the school spectra practical compare different light sources?', a: OL(['Use a spectroscope to view <b>discharge tubes</b>, a filament and reflected sunlight.', 'Discharge tubes: bright emission lines.', 'Filament: continuous spectrum; sunlight: absorption lines if resolved.']) },
  { id: 'p8sp06', dp: '7.1.4', t: 'prac', q: 'Why might the sunlight part of the school spectra practical be invalid or inconclusive?', a: L(['Poor spectral resolution may conceal <b>narrow absorption lines</b>.', 'Improve sensitivity and focus; non-observation does not establish absence.']) },
  { id: 'p8sp07', dp: '7.1.5', t: 'con', q: 'How does an astronomical spectrograph separate and record wavelengths?', a: OL(['A telescope collects light; a <b>slit</b> selects the source.', 'A collimator makes a parallel beam.', 'A prism or grating separates wavelengths.', 'A detector records the spectrum.']) },
]});
DECKS.push({ id: 'phys-m8-ss', fa: 'fa1', title: 'Stellar spectra and classification', dps: ['8.1.5', '7.1.6'], cards: [
  { id: 'p8ss01', dp: '8.1.5', t: 'con', q: 'Why does a star usually show a continuous spectrum with absorption lines?', a: L(['Hot, dense stellar material produces a <b>continuum</b>.', 'Cooler outer layers absorb selected wavelengths.', 'Absorption lines identify particles in the <b>stellar atmosphere</b>.']) + N('Source: absorption by hydrogen in space. Correct: absorption in the cooler stellar atmosphere.') },
  { id: 'p8ss02', dp: '8.1.5', t: 'rec', q: 'What is the order of the main stellar spectral classes from hottest to coolest?', a: E('O → B → A → F → G → K → M') + L(['Hottest to coolest; generally <b>blue → white → yellow → red</b>.', 'Classification uses temperature and characteristic lines.', 'Hot conditions favour ions; cool conditions permit molecules.']) },
  { id: 'p8ss03', dp: '7.1.6', t: 'eq', q: 'How does Wien’s law determine a star’s surface temperature?', a: E('λ_{max}T = b') + L(['b = <b>2.898 × 10^{-3} m K</b>.', 'Measure continuum peak wavelength in metres.', 'Calculate T = b/λ_{max} in kelvin.']) },
  { id: 'p8ss04', dp: '7.1.6', t: 'calc', q: 'A stellar spectrum peaks at 458.0 nm. What is its surface temperature?', a: OL(['λ_{max} = 458.0 × 10^{-9} m.', 'T = (2.898 × 10^{-3}) ÷ (458.0 × 10^{-9}).', 'T = <b>6328 K</b> to four significant figures.']) + N('6300 K is a rough estimate; supplied data give 6328 K.') },
  { id: 'p8ss05', dp: '7.1.6', t: 'con', q: 'What do redshift and blueshift reveal about a star’s translational motion?', a: L(['<b>Redshift:</b> recession; <b>blueshift:</b> approach.', 'Only the line-of-sight velocity is measured.']) + E('v ≈ c(λ_{obs} − λ_0)/λ_0') + N('This light-Doppler relation assumes |v| ≪ c; the source’s sound-wave formula is not exact for light.') },
  { id: 'p8ss06', dp: '7.1.6', t: 'calc', q: 'Barnard’s star has a 0.24 nm blueshift of the 656 nm line. Estimate its radial velocity to two significant figures.', a: OL(['Δλ = −0.24 nm; the wavelength units cancel in the ratio.', 'v ≈ (3.00 × 10^8)(−0.24/656) = −1.09756 × 10^5 m s^{-1}.', 'v ≈ <b>−1.1 × 10^5 m s^{-1}</b>, or 110 km s^{-1} towards Earth.']) + L(['Its stated total speed of 143 km s^{-1} is larger because it also has motion perpendicular to the line of sight.']) + N('Source: 11 km s^{-1}. Correct: 110 km s^{-1} towards Earth.') },
  { id: 'p8ss07', dp: '7.1.6', t: 'con', q: 'How can rotation and atmospheric density each broaden stellar spectral lines?', a: L(['<b>Rotation:</b> approaching material is blueshifted, receding material redshifted; combined lines broaden.', '<b>Density:</b> more collisions cause pressure broadening.', 'Line width can have several causes.']) + N('The key reverses shifts: approach is blue; recession is red.') },
  { id: 'p8ss08', dp: '8.1.5', t: 'exam', q: '2016 HSC (4 marks): Describe how a star’s spectrum determines its chemical composition and surface temperature.', a: L(['Identify elements by matching <b>absorption-line patterns</b> to known laboratory spectra.', 'These lines form when particles in the cooler atmosphere absorb specific photon energies.', 'Measure the continuum’s <b>peak wavelength</b>.', 'Apply T = b/λ_{max}; spectral features also indicate molecular, neutral or ionised particles associated with temperature.']) },
  { id: 'p8ss09', dp: '7.1.6', t: 'exam', q: '2019 NESA sample (3 marks; Module 7 Q11): Croesus has narrow redshifted hydrogen lines; Dromus has broader, slightly blueshifted hydrogen lines. What motion does each spectrum indicate?', a: L(['<b>Croesus:</b> receding, shown by redshift; no resolved rotational broadening.', '<b>Dromus:</b> approaching, shown by blueshift; broader lines are consistent with rotation.', 'The matching line patterns identify hydrogen in both spectra.']) + N('Narrow lines do not prove zero rotation; broadening can also be pressure-related.') },
]});
DECKS.push({ id: 'phys-m8-hr', fa: 'fa1', title: 'H–R diagrams and main sequence stars', dps: ['8.1.6', '8.1.7'], cards: [
  { id: 'p8hr01', dp: '8.1.6', t: 'def', q: 'What quantities and axis directions define a Hertzsprung–Russell diagram?', a: L(['<b>Luminosity increases upwards</b>.', '<b>Surface temperature decreases rightwards</b>; colour and spectral class may also label this axis.', 'Scales are usually non-linear.']) },
  { id: 'p8hr02', dp: '8.1.6', t: 'con', q: 'Where are the main sequence, red giants and white dwarfs on an H–R diagram?', a: L(['<b>Main sequence:</b> upper left to lower right.', '<b>Red giants:</b> upper right; <b>white dwarfs:</b> lower left.', '<b>Supergiants:</b> high luminosity across the top.']) },
  { id: 'p8hr03', dp: '8.1.6', t: 'con', q: 'Why can a red giant be more luminous than a hotter white dwarf?', a: L(['Luminosity depends on <b>temperature and surface area</b>.', 'A red giant’s large area can outweigh its lower temperature.', 'A white dwarf is hot but small and faint.']) },
  { id: 'p8hr04', dp: '8.1.6', t: 'con', q: 'How do mass and lifetime change along the main sequence?', a: L(['Mass increases towards the <b>upper left</b>.', 'Higher core temperature gives faster fusion.', 'More massive stars exhaust fuel faster and have <b>shorter lifetimes</b>.']) },
  { id: 'p8hr05', dp: '8.1.7', t: 'con', q: 'What defines a main sequence star and keeps it approximately stable?', a: L(['Core <b>hydrogen fusion</b> produces helium.', 'Outward pressure balances inward <b>gravity</b>.', 'Excess pressure causes expansion; excess gravity causes contraction.']) },
  { id: 'p8hr08', dp: '8.1.7', t: 'con', q: 'Why do red dwarfs remain on the main sequence for so long?', a: L(['Low core temperatures give <b>slow fusion</b>.', 'Red dwarfs are cool and faint on the lower-right main sequence.', 'Predicted lifetimes exceed the Universe’s present age.']) + N('Conflicting low-mass limits and luminosities were not retained.') },
]});
DECKS.push({ id: 'phys-m8-pp', fa: 'fa1', title: 'Proton–proton fusion', dps: ['8.1.7'], cards: [
  { id: 'p8pp01', dp: '8.1.7', t: 'con', q: 'In which stars does the proton–proton chain predominantly produce energy?', a: L(['Dominant in lower-mass main sequence stars, including the <b>Sun</b>.', 'Typical core temperatures are about <b>10–15 million K</b>.', 'Hydrogen nuclei ultimately form helium.']) },
  { id: 'p8pp02', dp: '8.1.7', t: 'eq', q: 'What is the first step of the PP I chain?', a: E('^1_1H + ^1_1H → ^2_1H + ^0_{+1}e + ν') + L(['Two protons form a <b>deuteron</b>; one becomes a neutron.', 'A positron and neutrino are emitted.']) },
  { id: 'p8pp03', dp: '8.1.7', t: 'eq', q: 'What happens when a deuteron captures another proton in PP I?', a: E('^{2}_{1}H + ^{1}_{1}H → ^{3}_{2}He + γ') + L(['A <b>helium-3 nucleus</b> and a gamma photon are produced.', 'The booklet assigns approximately 5.49 MeV to this step.']) },
  { id: 'p8pp04', dp: '8.1.7', t: 'eq', q: 'What happens when two helium-3 nuclei combine in PP I?', a: E('^3_2He + ^3_2He → ^4_2He + 2^1_1H') + L(['Produces <b>helium-4</b> and returns two protons.', 'The previous two steps each occur twice.']) + N('Source: helium-3 is a triteron. Correct: a triton is hydrogen-3; this is helium-3.') },
  { id: 'p8pp05', dp: '8.1.7', t: 'eq', q: 'What is the net PP I equation before positron annihilation?', a: E('4 ^{1}_{1}H → ^{4}_{2}He + 2 ^{0}_{+1}e + 2ν + 2γ') + L(['<b>Four protons</b> ultimately produce one helium-4 nucleus.', 'The emitted positrons can subsequently annihilate with electrons.']) },
  { id: 'p8pp10', dp: '8.1.7', t: 'con', q: 'Why do detected solar neutrinos provide evidence for fusion in the Sun?', a: L(['Fusion predicts <b>solar neutrinos</b>.', 'Weak interactions let them escape readily.', 'Detected neutrinos support the fusion model.']) + N('Gamma photons repeatedly interact with solar matter; they do not escape like neutrinos.') },
]});
DECKS.push({ id: 'phys-m8-cn', fa: 'fa1', title: 'CNO cycle', dps: ['8.1.7'], cards: [
  { id: 'p8cn01', dp: '8.1.7', t: 'con', q: 'Why is the CNO cycle especially important in hotter, more massive main sequence stars?', a: L(['Higher core temperatures favour the <b>CNO cycle</b>.', 'C, N and O intermediates convert hydrogen into helium.', 'Regenerated carbon-12 acts as a <b>catalyst</b>.']) },
  { id: 'p8cn02', dp: '8.1.7', t: 'eq', q: 'Which three proton-capture reactions emit gamma photons in the CNO cycle?', a: E('^{12}_6C + ^1_1H → ^{13}_7N + γ') + E('^{13}_6C + ^1_1H → ^{14}_7N + γ') + E('^{14}_7N + ^1_1H → ^{15}_8O + γ') + L(['Successive captures build the nitrogen and oxygen intermediates.']) },
  { id: 'p8cn03', dp: '8.1.7', t: 'eq', q: 'Which two beta-plus decays occur in the CNO cycle?', a: E('^{13}_7N → ^{13}_6C + ^0_{+1}e + ν') + E('^{15}_8O → ^{15}_7N + ^0_{+1}e + ν') + L(['Each emits a <b>positron and neutrino</b>.']) + N('The key says antineutrino in both decays; beta-plus decay emits a neutrino.') },
  { id: 'p8cn07', dp: '8.1.7', t: 'eq', q: 'What reaction completes the CNO cycle and regenerates its catalyst?', a: E('^{15}_{7}N + ^{1}_{1}H → ^{12}_{6}C + ^{4}_{2}He') + L(['A helium-4 nucleus is produced and <b>carbon-12 is regenerated</b>.']) },
  { id: 'p8cn08', dp: '8.1.7', t: 'eq', q: 'What is the net CNO-cycle reaction before positron annihilation?', a: E('4 ^{1}_{1}H → ^{4}_{2}He + 2 ^{0}_{+1}e + 2ν + 3γ') + L(['The net change is <b>four protons into one helium-4 nucleus</b>.', 'C, N and O intermediates cancel when the six reactions are added.']) },
  { id: 'p8cn11', dp: '8.1.7', t: 'exam', q: '2019 NESA sample (4 marks; Q13): Describe TWO processes that account for energy production in stars.', a: L(['<b>Proton–proton chain:</b> dominant in lower-mass main sequence stars; a sequence of fusion reactions converts four protons into helium-4, with positrons, neutrinos and photons produced.', '<b>CNO cycle:</b> important in hotter, more massive main sequence stars; C, N and O intermediates catalyse the same net hydrogen-to-helium conversion.', 'In each, the products have lower total rest mass and <b>energy is released</b>.']) },
]});
DECKS.push({ id: 'phys-m8-ev', fa: 'fa1', title: 'Post-main sequence fusion and stellar evolution', dps: ['8.1.6', '8.1.7'], cards: [
  { id: 'p8ev01', dp: '8.1.7', t: 'con', q: 'Why does a star leave the main sequence when core hydrogen is depleted?', a: L(['Core hydrogen depletion reduces pressure support.', 'The core <b>contracts and heats</b>.', 'Hydrogen shell burning accompanies outer expansion into a giant.']) + N('Source: a universal 10% core-depletion threshold. Correct: usable core hydrogen becomes depleted.') },
  { id: 'p8ev02', dp: '8.1.7', t: 'eq', q: 'How does the triple-alpha process make carbon-12?', a: E('^4_2He + ^4_2He ⇌ ^8_4Be') + E('^8_4Be + ^4_2He → ^{12}_6C + γ') + L(['Three alpha particles form <b>carbon-12</b>.', 'Unstable Be-8 must capture another alpha rapidly.', 'Requires a hot core, around <b>10^8 K</b>.']) },
  { id: 'p8ev03', dp: '8.1.7', t: 'eq', q: 'How can helium capture form oxygen-16 after carbon production?', a: E('^{12}_{6}C + ^{4}_{2}He → ^{16}_{8}O + γ') + L(['Adding another alpha particle to carbon produces <b>oxygen-16</b>.']) + N('Source: three He-4 make O-16. Correct: three make C-12, then another He-4 makes O-16.') },
  { id: 'p8ev04', dp: '8.1.7', t: 'def', q: 'What is a helium flash?', a: L(['The rapid onset of <b>helium fusion</b> in the degenerate core of some lower-mass red giants.', 'It begins when the core becomes hot enough for the triple-alpha process.']) },
  { id: 'p8ev07', dp: '8.1.7', t: 'con', q: 'How do massive stars form heavier elements and why does fusion cease near the iron group?', a: L(['Successive core and shell burning makes heavier nuclei.', 'Fusion towards the <b>iron-group binding maximum</b> releases energy.', 'Fusion beyond it requires energy and cannot support the star in the same way.']) },
  { id: 'p8ev08', dp: '8.1.7', t: 'con', q: 'How do supernovae contribute to the origins of elements?', a: L(['Core collapse can produce a <b>supernova</b>.', 'Neutron capture forms heavier-than-iron elements.', 'Ejection enriches gas forming later stars and planets.']) },
  { id: 'p8ev09', dp: '8.1.6', t: 'con', q: 'What is the broad evolutionary route of a Sun-like star?', a: L(['Cloud → protostar → <b>main sequence → red giant</b>.', 'Outer layers are shed, leaving a <b>white dwarf</b>.', 'Stored heat is radiated; black dwarfs are predicted endpoints, but the Universe is too young for them.']) + N('White dwarfs radiate stored heat, not sustained fusion, and do not become brown dwarfs. Their 1.4-solar-mass limit concerns remnants.') },
  { id: 'p8ev10', dp: '8.1.6', t: 'con', q: 'How do neutron stars, pulsars and black holes arise in the booklet’s massive-star pathway?', a: L(['Core collapse can leave a <b>neutron star</b>.', 'A rotating neutron star is seen as a <b>pulsar</b> if its beam sweeps Earth.', 'An unsupported, sufficiently massive remnant collapses to a <b>black hole</b>.']) + N('Source confuses initial and remnant masses and calls core-collapse a nova. Correct: supernova.') },
]});
DECKS.push({ id: 'phys-m8-ef', fa: 'fa2', title: 'Fields, charge and calculation skills', dps: ['8.2.1', '6.1.3'], cards: [
  { id: 'p8ef01', dp: '8.2.1', t: 'def', q: 'What is an electric field and how is its direction defined?', a: L(['An electric field exerts a force on charge: <b>F = qE</b>.', 'Its direction is the force on positive charge.', 'Negative charge experiences the opposite force.']) },
  { id: 'p8ef02', dp: '8.2.1', t: 'eq', q: 'How are electric field, voltage and energy transfer related between parallel plates?', a: E('E = V/d') + E('W = qV') + L(['E is in <b>V m^{-1}</b> or N C^{-1}; d must be in metres.', 'Use the potential difference actually traversed by the particle.', 'For acceleration from rest, the electric work becomes kinetic energy: |q|V = mv^2/2.']) },
  { id: 'p8ef03', dp: '8.2.1', t: 'exam', q: '2020 HSC (marks not supplied; Q34 setup excerpt): A charged particle starts midway between plates with total voltage V and strikes one plate. What voltage change enters the energy calculation?', a: L(['The particle crosses half the plate separation in the uniform field.', 'Its potential-difference magnitude is <b>V/2</b>.', 'The electric work magnitude is therefore <b>|q|V/2</b>.']) + N('Only a setup excerpt is supplied; no marked sub-question is reproduced.') },
  { id: 'p8ef04', dp: '8.2.1', t: 'con', q: 'At fixed plate voltage, how does doubling plate separation affect an electron accelerated across the full gap?', a: L(['E = V/d, so doubling d <b>halves field and force</b>.', 'Travel distance doubles; work |q|V is unchanged.', 'Final kinetic energy and speed are unchanged for identical starting conditions.']) },
  { id: 'p8ef05', dp: '6.1.3', t: 'eq', q: 'When does a magnetic field exert a force on a charged particle?', a: E('F = |q|vBsinθ') + L(['The force is perpendicular to the particle’s velocity and the field.', 'It is maximum for <b>perpendicular motion</b> and zero for parallel motion or a stationary charge.', 'Use the right-hand rule for a positive charge; reverse the result for a negative charge.']) },
  { id: 'p8ef06', dp: '6.1.3', t: 'eq', q: 'What radius does a non-relativistic charged particle follow perpendicular to a uniform magnetic field?', a: E('|q|vB = mv^2/r') + E('r = mv/(|q|B)') + L(['Magnetic force supplies the <b>centripetal force</b>.', 'It changes direction while leaving speed and kinetic energy unchanged.', 'On leaving the field, the particle continues along the tangent if no other force acts.']) + N('Circular motion requires perpendicular entry; a parallel velocity component changes the path.') },
]});
DECKS.push({ id: 'phys-m8-cr', fa: 'fa2', title: 'Cathode rays and discharge-tube experiments', dps: ['8.2.1'], cards: [
  { id: 'p8cr01', dp: '8.2.1', t: 'def', q: 'What are cathode rays and which electrodes produce and attract them?', a: L(['A beam of <b>electrons</b> emitted from the negative cathode.', 'The positive anode attracts and accelerates them in a discharge tube.', 'Fluorescence reveals the beam. Thomson found |q|/m ≈ 1.76 × 10^{11} C kg^{-1} across different cathode materials, supporting common electrons in atoms.']) },
  { id: 'p8cr02', dp: '8.2.1', t: 'prac', q: 'How does reducing gas pressure change a discharge tube’s appearance?', a: L(['Compare discharge tubes at progressively lower gas pressures under high DC voltage.', 'Dark space expands as collisions decrease.', 'At low pressure the beam reaches the glass and causes <b>fluorescence</b>.']) },
  { id: 'p8cr03', dp: '8.2.1', t: 'prac', q: 'What did the Maltese-cross tube demonstrate?', a: L(['A metal cross produces a <b>sharp shadow</b> on the fluorescent screen.', 'Cathode rays travel straight and are blocked by metal.']) },
  { id: 'p8cr04', dp: '8.2.1', t: 'prac', q: 'What did the paddle-wheel tube suggest, and why was it not decisive by itself?', a: L(['A paddle wheel rotates in the beam, suggesting <b>energy and momentum transfer</b>.', 'Supported particle behaviour but did not settle the historical debate alone.']) },
  { id: 'p8cr05', dp: '8.2.1', t: 'prac', q: 'How did a fluorescent screen and a magnet reveal properties of cathode rays?', a: L(['A slit and fluorescent screen reveal the beam path.', 'Magnetic deflection is consistent with <b>moving negative charges</b>.']) },
  { id: 'p8cr06', dp: '8.2.1', t: 'prac', q: 'How did electric-plate experiments support the electron interpretation?', a: L(['The beam deflects towards the <b>positive plate</b>.', 'This demonstrates negative charge.', 'Improved apparatus resolved the deflection Hertz initially failed to observe.']) },
  { id: 'p8cr07', dp: '8.2.1', t: 'prac', q: 'How did Perrin directly test the charge carried by cathode rays?', a: L(['Perrin collected the beam in an electroscope-connected cylinder.', 'The collector gained <b>negative charge</b>.']) },
  { id: 'p8cr09', dp: '8.2.1', t: 'con', q: 'Why did early cathode-ray observations cause a wave-versus-particle debate?', a: L(['Straight travel, fluorescence and chemical effects resembled radiation.', 'Momentum transfer, negative charge and field deflection supported <b>particles</b>.', 'Improved experiments established electrons; later diffraction showed wave behaviour.']) + N('Waves can spread by diffraction, contrary to the key; beam spreading alone is not decisive.') },
]});
DECKS.push({ id: 'phys-m8-tm', fa: 'fa2', title: 'Thomson and the charge-to-mass ratio', dps: ['8.2.1'], cards: [
  { id: 'p8tm04', dp: '8.2.1', t: 'calc', q: 'A balanced beam passes between plates 5.0 cm apart at 500 V with B = 10 mT. Calculate its speed.', a: OL(['d = 0.050 m; B = 0.010 T.', 'E = V/d = 500/0.050 = 1.0 × 10^4 V m^{-1}.', 'v = E/B = (1.0 × 10^4)/0.010 = <b>1.0 × 10^6 m s^{-1}</b>.']) + L(['For electrons travelling right with the positive plate above, a magnetic field <b>into the page</b> balances the upward electric force.']) },
  { id: 'p8tm05', dp: '8.2.1', t: 'calc', q: 'An electron accelerates from rest through 300 V. What non-relativistic speed does it reach to two significant figures?', a: OL(['|q|V = mv^2/2, so v = √(2|q|V/m).', 'v = √[2(1.602 × 10^{-19})(300)/(9.109 × 10^{-31})].', 'v = 1.02724 × 10^7 m s^{-1} ≈ <b>1.0 × 10^7 m s^{-1}</b>.']) },
  { id: 'p8tm06', dp: '8.2.1', t: 'calc', q: 'The 300 V electron beam curves with radius 10 cm in B = 5.0 × 10^{-4} T. What charge-to-mass ratio does this data give?', a: OL(['Use unrounded v = 1.027239 × 10^7 m s^{-1}; r = 0.10 m.', '|q|/m = v/(Br).', '|q|/m = (1.027239 × 10^7)/[(5.0 × 10^{-4})(0.10)] = <b>2.1 × 10^{11} C kg^{-1}</b>.']) },
  { id: 'p8tm07', dp: '8.2.1', t: 'exam', q: '2017 NESA sample (3 marks; graph part): Plot v^2 against voltage for (100, 0.8), (200, 2.1), (300, 3.1), (400, 4.1), (500, 5.2), with v^2 in 10^9 m^2 s^{-2}. What graph should result?', a: L(['Label voltage in <b>V</b> on the horizontal axis and v^2 in <b>10^9 m^2 s^{-2}</b> vertically.', 'Choose suitable scales, plot all five points and draw a <b>straight line of best fit</b>.', 'The gradient is approximately <b>1.1 × 10^7 m^2 s^{-2} V^{-1}</b>.']) },
  { id: 'p8tm08', dp: '8.2.1', t: 'exam', q: '2017 NESA sample (3 marks; identification part): Does a v^2–V gradient of approximately 1.1 × 10^7 m^2 s^{-2} V^{-1} identify the negative particles as electrons?', a: OL(['|q|V = mv^2/2 gives gradient = 2|q|/m.', '|q|/m ≈ (1.1 × 10^7)/2 = 5.5 × 10^6 C kg^{-1}.', 'For electrons, |q|/m = (1.602 × 10^{-19})/(9.109 × 10^{-31}) = 1.759 × 10^{11} C kg^{-1}.', 'The measured ratio is far smaller: <b>the particles are not electrons</b>.']) },
  { id: 'p8tm09', dp: '8.2.1', t: 'exam', q: '2014 HSC, modified (3 marks): Use an annotated diagram to show how Thomson’s experiment measures the electron’s charge-to-mass ratio.', a: L(['A cathode and slit anode produce a narrow electron beam in an <b>evacuated tube</b>; a fluorescent screen shows its path.', 'Opposing electric and magnetic forces balance to give v = E/B.', 'With the electric field off, measure r in the magnetic field and calculate <b>|q|/m = v/(Br)</b>.']), v: 'thomson' },
]});
DECKS.push({ id: 'phys-m8-od', fa: 'fa2', title: 'Millikan and quantised charge', dps: ['8.2.1'], cards: [
  { id: 'p8od01', dp: '8.2.1', t: 'prac', q: 'How did Millikan use fields to measure the charge on an oil drop?', a: OL(['Spray tiny oil drops between horizontal charged plates and charge them using ionising radiation.', 'Observe a drop through a microscope and adjust the <b>voltage</b> until it remains stationary.', 'Its upward electric force balances downward weight.']) + E('|q|E = mg') + E('|q| = mgd/V') },
  { id: 'p8od02', dp: '8.2.1', t: 'prac', q: 'How did Millikan estimate the mass of an oil drop?', a: L(['Measure <b>terminal falling speed</b> with the field off.', 'Use fluid resistance to determine drop radius.', 'Calculate mass from volume and oil density.']) + N('Air resistance matters during falling; the simple suspended-drop equation omits small corrections.') },
  { id: 'p8od03', dp: '8.2.1', t: 'con', q: 'What did Millikan’s measurements establish about electric charge?', a: L(['Drop charges were integer multiples of the <b>elementary charge</b>.', 'e ≈ 1.602 × 10^{-19} C; an electron carries −e.', 'Combining e with Thomson’s |q|/m determines electron mass.']) + N('Source credits oil-drop quantisation to Thomson. Correct: Millikan.') },
  { id: 'p8od04', dp: '8.2.1', t: 'exam', q: '2019 NESA sample (6 marks; Q25): Sealed identical boxes have successive mass differences 21.5, 25.8, 4.3, 8.6, 12.9 and 43.0 g. Assess the domino model of Millikan’s experiment.', a: L(['The differences equal <b>5, 6, 1, 2, 3 and 10 multiples of 4.3 g</b>.', 'This models quantisation: whole dominoes resemble whole elementary-charge increments.', 'The common box mass cancels when differences are compared.', 'The smallest observed difference does not prove it is one domino; more trials help test that assumption.', 'The model is <b>effective for the data-analysis logic</b>, although it uses mass measurements rather than charged drops and balanced fields.']) },
  { id: 'p8od05', dp: '8.2.1', t: 'calc', q: 'A 2.5 × 10^{-15} kg drop is suspended between plates 3.0 mm apart, positive plate above. Find its charges at 75, 105, 175, 260 and 550 V.', a: OL(['The field points down; the upward electric force requires a <b>negative charge</b>.', 'q = −mgd/V = −[(2.5 × 10^{-15})(9.8)(3.0 × 10^{-3})]/V.', 'For 75, 105, 175, 260 and 550 V respectively: <b>−9.8, −7.0, −4.2, −2.8 and −1.3 × 10^{-19} C</b>, to two significant figures.']) + N('Last two unrounded charges: −2.82692 and −1.33636 × 10^{-19} C; the key’s values are incorrect.') },
  { id: 'p8od07', dp: '8.2.1', t: 'exam', q: '2021 HSC (4 marks; Q23): Describe how Millikan and Thomson each used fields to determine properties of the electron.', a: L(['<b>Thomson:</b> balanced electric and magnetic forces on a beam to determine speed, then used magnetic deflection to calculate the electron’s charge-to-mass ratio.', '<b>Millikan:</b> balanced electric force against gravitational force on charged oil droplets, determined their charges and found integer multiples of the elementary charge.']) },
]});
DECKS.push({ id: 'phys-m8-nm', fa: 'fa2', title: 'Nuclear evidence, protons and neutrons', dps: ['8.2.2'], cards: [
  { id: 'p8nm02', dp: '8.2.2', t: 'prac', q: 'How was the Geiger–Marsden gold-foil experiment performed?', a: L(['Direct collimated alpha particles at <b>thin gold foil</b>.', 'Detect scintillations at different angles.', 'Most pass through; very few scatter through large angles or backwards.']) },
  { id: 'p8nm03', dp: '8.2.2', t: 'con', q: 'How did gold-foil scattering support Rutherford’s nuclear model?', a: L(['Most pass through: the atom is <b>mostly empty space</b>.', 'Rare large deflections require concentrated positive charge and mass.', 'A small dense nucleus is surrounded by electrons, contradicting electrons embedded in diffuse positive charge.']) },
  { id: 'p8nm04', dp: '8.2.2', t: 'prac', q: 'How can the golf-ball and table-tennis-ball activity model alpha scattering?', a: L(['Roll small balls towards a fixed golf ball from different paths.', 'Many miss; close encounters deflect, modelling a small scattering centre.', 'Contact collisions do not reproduce <b>electrostatic forces</b> or atomic scale.']) },
  { id: 'p8nm05', dp: '8.2.2', t: 'con', q: 'How did canal rays and Rutherford’s nitrogen experiment provide evidence for protons?', a: L(['Goldstein’s canal rays were <b>positive gas ions</b>; hydrogen supplied the lightest.', 'Rutherford identified hydrogen nuclei from alpha bombardment of nitrogen.']) + E('^{14}_7N + ^4_2He → ^{17}_8O + ^1_1H') + N('Source attributes proton discovery to gold foil. Correct: nitrogen bombardment identified hydrogen nuclei.') },
  { id: 'p8nm06', dp: '8.2.2', t: 'prac', q: 'What did Chadwick do to identify the neutron?', a: OL(['Bombard <b>beryllium with alpha particles</b>.', 'The neutral radiation ejects protons from paraffin.', 'Use recoil motion and conservation of energy and momentum.', 'Infer neutral particles with roughly proton mass.']) + E('^9_4Be + ^4_2He → ^{12}_6C + ^1_0n') },
  { id: 'p8nm07', dp: '8.2.2', t: 'exam', q: '2010 HSC (3 marks): How did Chadwick apply conservation laws in discovering the neutron?', a: L(['Used radiation produced by alpha bombardment of beryllium to eject protons from paraffin.', 'Measured proton speeds to obtain their <b>kinetic energy and momentum</b>.', 'Applied <b>conservation of energy and momentum</b> to the collision; the results required neutral projectiles with masses similar to protons and were inconsistent with the gamma-ray explanation.']) },
  { id: 'p8nm08', dp: '8.2.2', t: 'con', q: 'How did neutron discovery explain isotopes and missing nuclear mass?', a: L(['Same proton number means the same <b>element</b>.', 'Different neutron numbers give <b>isotopes</b>.', 'Neutrons explain nuclear mass beyond that supplied by protons.']) },
  { id: 'p8nm09', dp: '8.2.2', t: 'prac', q: 'What are the strengths and limitations of the ball-collision model of Chadwick’s experiment?', a: L(['Ball collisions model recoil and <b>momentum transfer</b>.', 'Groups represent source and target.', 'They do not model nuclear reactions, particle creation or actual scales.']) },
]});
DECKS.push({ id: 'phys-m8-bo', fa: 'fa3', title: 'Rutherford, Bohr and the Balmer spectrum', dps: ['8.3.1', '8.3.2', '8.3.3'], cards: [
  { id: 'p8bo02', dp: '8.3.1', t: 'exam', q: '2017 HSC (2 marks): Why were Bohr’s stable electron orbits incompatible with classical physics?', a: L(['An orbiting electron is an <b>accelerating charge</b>.', 'Classical electromagnetism predicts radiation, energy loss and spiralling into the nucleus.', 'Bohr instead postulated stationary states in which electrons <b>do not radiate</b>.']) },
  { id: 'p8bo03', dp: '8.3.2', t: 'prac', q: 'How can the Balmer emission spectrum be produced and observed?', a: OL(['Excite low-pressure <b>hydrogen</b> with high voltage.', 'Separate its light using a spectroscope.', 'Observe lines near <b>656, 486, 434 and 410 nm</b>.']) },
  { id: 'p8bo04', dp: '8.3.3', t: 'rec', q: 'What are Bohr’s three postulates?', a: L(['Allowed <b>stationary states</b> do not radiate.', 'Transitions exchange photons with <b>hf equal to the energy gap</b>.', 'Angular momentum is quantised: <b>mvr = nh/(2π)</b>.']) },
  { id: 'p8bo06', dp: '8.3.2', t: 'con', q: 'Which final levels identify Lyman, Balmer and Paschen emission series?', a: L(['<b>Lyman:</b> transitions to n = 1; ultraviolet.', '<b>Balmer:</b> transitions to n = 2; the first four prominent lines are visible.', '<b>Paschen:</b> transitions to n = 3; infrared.']) + N('Not all Balmer lines are visible. Brackett ends at n = 4 and Pfund at n = 5, both infrared.') },
  { id: 'p8bo08', dp: '8.3.3', t: 'exam', q: '2012 HSC (3 marks): Using text and a diagram, outline Bohr’s explanation of the Balmer series.', a: L(['Electrons occupy <b>discrete stationary energy levels</b>.', 'Excited electrons fall from n = 3, 4, 5 or 6 to <b>n = 2</b>.', 'Each emits a photon with hf = E_i − E_f, producing a specific wavelength and hence a discrete spectral line.']), v: 'balmer' },
  { id: 'p8bo09', dp: '8.3.1', t: 'exam', q: '2012 HSC (2 marks): Outline TWO atomic-emission observations the Rutherford–Bohr model could not fully explain.', a: L(['Different <b>relative intensities</b> of emission lines.', '<b>Splitting of spectral lines in a magnetic field</b>, the Zeeman effect.']) },
  { id: 'p8bo10', dp: '8.3.1', t: 'exam', q: '2016 HSC (3 marks): Outline features of the hydrogen spectrum that Bohr’s model could not explain.', a: L(['Different <b>line intensities</b>.', 'Fine structure resolved within spectral lines.', '<b>Zeeman splitting</b> when a magnetic field is applied.']) + N('Fine, hyperfine and Zeeman structure are distinct; the source conflates them.') },
]});
DECKS.push({ id: 'phys-m8-hy', fa: 'fa3', title: 'Hydrogen energy levels and spectral calculations', dps: ['8.3.3'], cards: [
  { id: 'p8hy01', dp: '8.3.3', t: 'eq', q: 'How are photon energy and electron energy change related in an emission?', a: E('E_{photon} = E_i − E_f = hf = hc/λ') + L(['The photon has <b>positive energy</b>.', 'The electron’s own change is ΔE_{electron} = E_f − E_i, which is negative for emission.', 'Use h = 6.626 × 10^{-34} <b>J s</b> and c = 3.00 × 10^8 m s^{-1}.']) + N('Emission photon energy is E_i − E_f > 0; electron ΔE is negative. Planck’s constant has units J s.') },
  { id: 'p8hy02', dp: '8.3.3', t: 'eq', q: 'How is Rydberg’s equation used for a hydrogen emission line?', a: E('1/λ = R(1/n_f^2 − 1/n_i^2)') + L(['R = <b>1.097 × 10^7 m^{-1}</b>.', 'For emission n_i > n_f; for Balmer emission n_f = 2.', 'The equation gives <b>inverse wavelength</b>; invert to obtain λ in metres.']) },
  { id: 'p8hy03', dp: '8.3.3', t: 'calc', q: 'Using R = 1.097 × 10^7 m^{-1}, calculate the first four Balmer wavelengths.', a: OL(['Use 1/λ = R(1/4 − 1/n_i^2), then invert; n_i = 3, 4, 5, 6.', 'For n_i = 3: 1/λ = (1.097 × 10^7)(1/4 − 1/9) = 1.523611 × 10^6 m^{-1}.', 'λ = 6.5633546 × 10^{-7} m = <b>656.3 nm</b>.', 'For n_i = 4, 5 and 6, the inverse wavelengths are 2.056875 × 10^6, 2.3037 × 10^6 and 2.437778 × 10^6 m^{-1}.', 'Inverting gives <b>486.2, 434.1 and 410.2 nm</b>, respectively.']) + N('The rounded R gives these calculated values; the booklet quotes observed wavelengths 656.2, 486.1, 434.0 and 410.1 nm.') },
  { id: 'p8hy07', dp: '8.3.3', t: 'exam', q: '2017 HSC (4 marks): With reference to Bohr’s postulates, explain the 434.0 nm hydrogen line and support your answer by calculation.', a: L(['Electrons occupy <b>stationary, quantised states</b> and emit a photon when moving to a lower state.', 'This Balmer line ends at <b>n_f = 2</b>.']) + OL(['1/(434.0 × 10^{-9}) = (1.097 × 10^7)(1/4 − 1/n_i^2).', '1/n_i^2 ≈ 0.0399592; n_i ≈ 5.0026, giving the integer level <b>n_i = 5</b>.', 'The n = 5 → 2 transition emits E = hc/λ = <b>4.58 × 10^{-19} J</b>.']) },
  { id: 'p8hy08', dp: '8.3.3', t: 'exam', q: '2016 HSC (3 marks): A hydrogen electron emits 4.089 × 10^{-19} J on reaching n = 2. Calculate its initial level.', a: OL(['E = hcR(1/4 − 1/n_i^2).', '1/n_i^2 = 1/4 − (4.089 × 10^{-19})/[(6.626 × 10^{-34})(3.00 × 10^8)(1.097 × 10^7)].', 'n_i ≈ 4.0005; energy levels are integers, so <b>n_i = 4</b>.']) },
  { id: 'p8hy09', dp: '8.3.3', t: 'calc', q: 'Using Rydberg’s equation, determine the wavelength and energy needed to ionise ground-state hydrogen.', a: OL(['For n = 1 to infinity, use the positive energy-gap magnitude: 1/λ = R.', 'λ = 1/(1.097 × 10^7) = <b>9.116 × 10^{-8} m</b>.', 'f = c/λ = <b>3.29 × 10^{15} Hz</b>.', 'E = hf = <b>2.18 × 10^{-18} J</b>.', 'E/e = 13.6118 eV ≈ <b>13.6 eV</b>, consistent with the quoted experimental ionisation energy.']) },
  { id: 'p8hy12', dp: '8.3.3', t: 'calc', q: 'An atom’s levels are −5.26, −3.49, −2.07, −1.56, −1.29 and −1.18 eV. Can a 643.7 nm photon excite it from the ground state?', a: OL(['E_{photon} = hc/λ = [(6.626 × 10^{-34})(3.00 × 10^8)]/(643.7 × 10^{-9}).', 'E_{photon} = 1.92764 eV ≈ 1.93 eV.', 'Ground-state gaps are 1.77, 3.19, 3.70, 3.97 and 4.08 eV.', 'None matches: <b>no allowed ground-state excitation</b> is produced by that photon.']) + N('The key confuses absorption and emission. From n = 2, about 1.93 eV can excite 2 → 4; return f ≈ 4.66 × 10^{14} Hz, not 8.93 × 10^{14}.') },
  { id: 'p8hy14', dp: '8.3.3', t: 'con', q: 'Why would a predicted hydrogen line near 122 nm be invisible in a school optical spectroscope?', a: L(['It corresponds approximately to the <b>n = 2 → 1</b> energy gap.', '122 nm is <b>ultraviolet</b>, outside the visible range.', 'A school visible-light spectroscope and the eye do not detect it.']) + N('Source: 122 nm is infrared. Correct: ultraviolet.') },
]});
DECKS.push({ id: 'phys-m8-mw', fa: 'fa3', title: 'Matter waves and diffraction evidence', dps: ['8.3.4'], cards: [
  { id: 'p8mw01', dp: '8.3.4', t: 'eq', q: 'What is de Broglie’s matter-wave relationship?', a: E('λ = h/p = h/(mv)') + L(['Matter-wave wavelength is inversely proportional to <b>momentum</b>.', 'Use p = mv for non-relativistic motion.']) + N('Photon p = E/c = h/λ; photons have zero rest mass, despite the source’s mass wording.') },
  { id: 'p8mw02', dp: '8.3.4', t: 'def', q: 'What are diffraction and Bragg’s condition for constructive interference?', a: L(['<b>Diffraction:</b> wave spreading at apertures or obstacles.', 'Crystal reflections reinforce when path difference is nλ.']) + E('nλ = 2dsinθ') + L(['d: plane spacing; θ: angle to planes; n: order.']) },
  { id: 'p8mw03', dp: '8.3.4', t: 'prac', q: 'What observations did Davisson and Germer make with electrons and nickel?', a: L(['Scatter electrons from a <b>nickel crystal</b> in vacuum.', 'Measure angular intensity maxima and minima.', 'The diffraction pattern demonstrates electron wave behaviour.']) },
  { id: 'p8mw06', dp: '8.3.4', t: 'prac', q: 'How does the vibrating-ring demonstration model electron standing waves?', a: L(['Drive a ring with a vibrator at different frequencies.', 'Resonances produce stable nodes and antinodes.', 'Models <b>allowed modes</b>, not a literal electron orbit.']) },
  { id: 'p8mw07', dp: '8.3.4', t: 'exam', q: '2015 HSC (2 marks): State Davisson and Germer’s conclusion with reference to their electron-scattering results.', a: L(['Scattered electrons produced <b>diffraction intensity maxima and minima</b>.', 'As diffraction results from wave interference, the electrons exhibit <b>wave behaviour</b>.']) },
  { id: 'p8mw08', dp: '8.3.4', t: 'exam', q: '2015 HSC (3 marks): Explain the significance of Davisson and Germer’s experiment for the Rutherford–Bohr model.', a: L(['It provided evidence for <b>de Broglie’s electron waves</b>.', 'Allowed electron states can be modelled as standing waves satisfying 2πr = nλ.', 'This supplied a wave-based explanation for quantisation that Bohr had introduced as a postulate.']) },
  { id: 'p8mw09', dp: '8.3.4', t: 'exam', q: '2017 HSC (3 marks): How did de Broglie, and Davisson and Germer, contribute to modification of the Bohr model?', a: L(['<b>De Broglie</b> proposed moving electrons have wavelength λ = h/p.', 'Whole-number wavelengths around a closed path explained discrete allowed modes and Bohr’s angular-momentum condition.', '<b>Davisson and Germer</b> observed electron diffraction from nickel, supporting the matter-wave hypothesis.']) },
  { id: 'p8mw11', dp: '8.3.4', t: 'con', q: 'What standing-wave condition represents the n = 4 electron state in de Broglie’s ring model?', a: E('2πr = 4λ') + L(['<b>Four complete wavelengths</b> fit around the circumference.', 'The wave joins smoothly after one circuit, forming an allowed mode; generally 2πr = nλ.']) + N('Standing-wave states do not remove electron charge, contrary to the source’s wording.') },
]});
DECKS.push({ id: 'phys-m8-mc', fa: 'fa3', title: 'Matter-wave calculations', dps: ['8.3.4'], cards: [
  { id: 'p8mc01', dp: '8.3.4', t: 'calc', q: 'For a 120 g ball, calculate λ at 10 m s^{-1} and 40 m s^{-1}, to three significant figures as the worksheet requests.', a: OL(['m = 0.120 kg; λ = h/(mv).', 'At 10 m s^{-1}: λ = (6.626 × 10^{-34})/(0.120 × 10) = <b>5.52 × 10^{-34} m</b>.', 'At 40 m s^{-1}: λ = (6.626 × 10^{-34})/(0.120 × 40) = <b>1.38 × 10^{-34} m</b>.', 'Quadrupling speed quarters the wavelength.']) },
  { id: 'p8mc06', dp: '8.3.4', t: 'calc', q: 'How slowly must a 150 g ball move to match the wavelength of a proton of mass 1.673 × 10^{-27} kg travelling at 2.00 × 10^4 m s^{-1}?', a: OL(['Equal wavelength means equal <b>momentum</b>: m_{ball}v_{ball} = m_pv_p.', 'v_{ball} = [(1.673 × 10^{-27})(2.00 × 10^4)]/0.150.', 'v_{ball} = <b>2.23 × 10^{-22} m s^{-1}</b> to the worksheet’s three significant figures.']) },
  { id: 'p8mc07', dp: '8.3.4', t: 'calc', q: 'A proton accelerates from rest through 50.0 V. Find its wavelength and the frequency of equal-wavelength X-rays.', a: OL(['|q|V = mv^2/2: v = √[2(1.602 × 10^{-19})(50.0)/(1.673 × 10^{-27})].', 'Retain v = 97 855.0595 m s^{-1}.', 'λ = (6.626 × 10^{-34})/[(1.673 × 10^{-27})(97 855.0595)] = <b>4.05 × 10^{-12} m</b>.', 'Using unrounded λ, f_{X-ray} = c/λ = (3.00 × 10^8)/(4.04736345 × 10^{-12}) = <b>7.41 × 10^{19} Hz</b>.']) },
  { id: 'p8mc10', dp: '8.3.4', t: 'calc', q: 'An electron beam has λ = 3.00 × 10^{-10} m. Calculate its speed and kinetic energy in eV.', a: OL(['v = h/(m_eλ) = (6.626 × 10^{-34})/[(9.109 × 10^{-31})(3.00 × 10^{-10})].', 'v = <b>2.42 × 10^6 m s^{-1}</b>.', 'K = m_ev^2/2; use unrounded v = 2.424708 × 10^6 m s^{-1}.', 'K/e = 16.7146 eV ≈ <b>16.7 eV</b>.']) },
  { id: 'p8mc11', dp: '8.3.4', t: 'calc', q: 'An alpha particle of mass 6.64 × 10^{-27} kg accelerates through 180.0 V. Find its speed, λ and the frequency of equal-wavelength X-rays.', a: OL(['q = 2e = 3.204 × 10^{-19} C.', 'v = √(2qV/m) = √[2(3.204 × 10^{-19})(180.0)/(6.64 × 10^{-27})] = <b>1.32 × 10^5 m s^{-1}</b>.', 'Using unrounded v, λ = h/(mv) = <b>7.57 × 10^{-13} m</b>.', 'f_{X-ray} = c/λ = <b>3.96 × 10^{20} Hz</b>.']) + N('Recalculated results are 7.57 × 10^{-13} m and 3.96 × 10^{20} Hz, replacing 7.56 and 3.97.') },
  { id: 'p8mc12', dp: '8.3.4', t: 'exam', q: '2015 HSC (2 marks): Calculate the speed of neutrons with wavelength 0.20 nm.', a: OL(['λ = 0.20 × 10^{-9} m = 2.0 × 10^{-10} m.', 'v = h/(m_nλ) = (6.626 × 10^{-34})/[(1.675 × 10^{-27})(2.0 × 10^{-10})].', 'v = <b>2.0 × 10^3 m s^{-1}</b> to two significant figures.']) },
  { id: 'p8mc13', dp: '8.3.4', t: 'exam', q: '2015 HSC (3 marks): Why is a 0.20 nm neutron beam useful for determining material structure?', a: L(['Its <b>short matter-wave wavelength</b> is comparable with atomic spacings.', 'Diffraction patterns reveal the arrangement of atoms.', 'Neutrons are electrically neutral, so electrostatic interactions do not prevent them from probing the material’s interior.']) },
  { id: 'p8mc14', dp: '8.3.4', t: 'calc', q: 'An electron travels at 2.0 × 10^7 m s^{-1}. Calculate its momentum and wavelength.', a: OL(['p = mv = (9.109 × 10^{-31})(2.0 × 10^7) = 1.8218 × 10^{-23} kg m s^{-1}.', 'p = <b>1.8 × 10^{-23} kg m s^{-1}</b> to two significant figures.', 'λ = h/p = (6.626 × 10^{-34})/(1.8218 × 10^{-23}) = <b>3.6 × 10^{-11} m</b>.']) + N('Source: 4.0 × 10^{-11} m. Correct: 3.6 × 10^{-11} m.') },
]});
DECKS.push({ id: 'phys-m8-qm', fa: 'fa3', title: 'Schrödinger, orbitals and quantum principles', dps: ['8.3.5'], cards: [
  { id: 'p8qm01', dp: '8.3.5', t: 'con', q: 'What did Schrödinger contribute to the atomic model?', a: L(['A <b>wave equation</b> determines allowed electron states and energies.', 'Solutions describe three-dimensional <b>orbitals</b>.', 'Location is described by probability.']) },
  { id: 'p8qm02', dp: '8.3.5', t: 'def', q: 'How does an orbital differ from an orbit?', a: L(['<b>Orbit:</b> a definite path.', '<b>Orbital:</b> a quantum state with a three-dimensional probability distribution.', 'Greater cloud density means greater probability of finding the electron.']) },
  { id: 'p8qm03', dp: '8.3.5', t: 'rec', q: 'What do the four electron quantum numbers describe?', a: L(['<b>n:</b> principal energy level and general orbital size.', '<b>l:</b> orbital shape or subshell; l = 0, 1, 2, 3 corresponds to s, p, d, f. The s distribution is spherical; p distributions are lobed.', '<b>m_l:</b> orbital orientation.', '<b>m_s:</b> spin state, +1/2 or −1/2.']) + N('l describes shape; m_l describes orientation. The source confuses them.') },
  { id: 'p8qm04', dp: '8.3.5', t: 'con', q: 'What does the Pauli exclusion principle say about electrons in an atom?', a: L(['No two electrons have the same <b>four quantum numbers</b>.', 'Each orbital holds at most two electrons with <b>opposite spin</b>.', 'This constrains electronic structure.']) + N('A complete state including spin holds one electron; a spatial orbital can hold two opposite-spin electrons.') },
  { id: 'p8qm05', dp: '8.3.5', t: 'con', q: 'What does Heisenberg’s uncertainty principle imply for electron position and momentum?', a: L(['Position and momentum cannot both have arbitrarily small uncertainty.', 'This is a <b>fundamental quantum limit</b>.']) + E('ΔxΔp ≥ h/(4π)') + N('Replace the source’s equalities with ΔxΔp ≥ h/(4π).') },
  { id: 'p8qm06', dp: '8.3.5', t: 'con', q: 'Why should electron spin not be described literally as a tiny ball rotating?', a: L(['Spin is <b>intrinsic quantum angular momentum</b>, associated with magnetic behaviour.', 'Electron spin states are +1/2 and −1/2.', 'It is not literal rotation of a tiny ball.']) + N('The source’s literal clockwise/anticlockwise rotating-ball description is misleading.') },
  { id: 'p8qm07', dp: '8.3.5', t: 'exam', q: '2021 HSC (5 marks; Q29): How does the nature of the electron differ in the Bohr, de Broglie and Schrödinger models?', a: L(['<b>Bohr:</b> a particle in an allowed, non-radiating circular orbit; transitions exchange quantised photon energy.', '<b>De Broglie:</b> the moving electron has a matter-wave wavelength and allowed states correspond to standing-wave modes.', '<b>Schrödinger:</b> a wavefunction describes the electron’s allowed state and probability distribution in a three-dimensional orbital.', 'The progression replaces a definite trajectory with a <b>probabilistic quantum description</b>.']) },
]});
DECKS.push({ id: 'phys-m8-ae', fa: 'fa3', title: 'HSC synthesis: development of atomic models', dps: ['8.3.1', '8.3.2', '8.3.4'], cards: [
  { id: 'p8ae01', dp: '8.3.1', t: 'exam', q: '2013 HSC (2 marks): Outline the key features of Rutherford’s model.', a: L(['A <b>small, dense, positive nucleus</b> contains most of the mass.', 'Electrons occupy the surrounding region; the atom is <b>mostly empty space</b>.']) },
  { id: 'p8ae02', dp: '8.3.1', t: 'exam', q: '2013 HSC (3 marks): Explain how Bohr’s model overcomes one limitation of Rutherford’s model.', a: L(['Rutherford’s model could not explain <b>discrete hydrogen emission lines</b>.', 'Bohr introduced discrete stationary energy levels.', 'Transitions emit photons satisfying hf = E_i − E_f, so only particular frequencies occur.']) },
  { id: 'p8ae03', dp: '8.3.4', t: 'exam', q: '2013 HSC (6 marks): How did de Broglie use existing ideas to increase understanding of matter?', a: L(['Bohr’s model already used stationary, quantised electron states but did not explain their allowed values.', 'Light showed both wave effects and photon behaviour, motivating de Broglie to propose analogous <b>wave behaviour for matter</b>.', 'He related wavelength to momentum using <b>λ = h/p</b>.', 'Electron states could be represented by whole-number standing-wave modes: 2πr = nλ.', 'This reproduced Bohr’s angular-momentum condition and supplied a reason for quantisation.', 'Electron diffraction later provided experimental support, expanding understanding beyond classical particles in orbits.']) },
  { id: 'p8ae04', dp: '8.3.2', t: 'exam', q: '2015 HSC (4 marks): Explain why the spectroscope was important in developing Bohr’s model.', a: L(['It separated emitted light into individual <b>wavelengths</b>.', 'Hydrogen showed discrete lines instead of the continuous emission expected from unrestricted classical orbits.', 'E = hf linked those wavelengths to specific <b>energy differences</b>.', 'Bohr proposed quantised stationary states and transitions to explain the observations.']) },
  { id: 'p8ae05', dp: '8.3.1', t: 'exam', q: '2014 HSC (6 marks): Assess the Rutherford–Bohr model’s effectiveness in accounting for experimental observations.', a: L(['<b>Effective:</b> the concentrated nucleus accounts for gold-foil scattering.', 'Quantised levels explain hydrogen spectra, its 13.6 eV ionisation energy and single-electron ions such as He^+ and Li^{2+}.', '<b>Limited:</b> the simple model does not fully explain multi-electron spectra, line intensities or resolved fine structure.', 'It cannot account fully for magnetic-field splitting of lines.', 'Non-radiating stationary states are postulated rather than justified using classical physics.', 'It is a successful model for important simple observations, but additional evidence requires a more complete <b>quantum model</b>.']) },
  { id: 'p8ae06', dp: '8.3.1', t: 'exam', q: '2019 NESA sample (8 marks; Q16): Analyse how observations and mathematical ideas improve scientific models, using atomic-model examples.', a: L(['Models explain observations and make predictions; a mismatch identifies a <b>limitation</b> and motivates revision.', 'Gold-foil scattering contradicted diffuse positive charge; Rutherford proposed a small, massive positive nucleus.', 'Hydrogen line spectra contradicted unrestricted classical orbits; Bohr introduced stationary quantised states and hf = E_i − E_f.', 'Rydberg’s equation connected predicted transitions with measured wavelengths and tested the model quantitatively.', 'De Broglie’s λ = h/p and 2πr = nλ gave a wave-based explanation of allowed states.', 'Davisson–Germer diffraction supplied independent evidence for electron waves, supporting further quantum development.']) },
]});
DECKS.push({ id: 'phys-m8-ns', fa: 'fa4', title: 'Nucleons, nuclear forces and stability', dps: ['8.4.1'], cards: [
  { id: 'p8ns01', dp: '8.4.1', t: 'def', q: 'What information does isotope notation ^{A}_{Z}X provide?', a: L(['<b>Z:</b> atomic number, equal to the number of protons.', '<b>A:</b> mass number, equal to protons plus neutrons.', '<b>N = A − Z:</b> number of neutrons.', 'Neutral atoms have Z electrons; ions gain or lose electrons. Integer A differs from average atomic mass.']) },
  { id: 'p8ns04', dp: '8.4.1', t: 'calc', q: 'Calculate the electrostatic repulsion between two protons 1.3 × 10^{-15} m apart.', a: OL(['F_E = e^2/(4πε_0r^2).', 'F_E = (1.602 × 10^{-19})^2/[4π(8.854 × 10^{-12})(1.3 × 10^{-15})^2].', 'F_E = 136.486 N ≈ <b>1.4 × 10^2 N</b>, repulsive, to two significant figures.']) },
  { id: 'p8ns05', dp: '8.4.1', t: 'calc', q: 'At the same 1.3 × 10^{-15} m separation, how does proton–proton gravity compare with electrostatic repulsion?', a: OL(['F_G = Gm_p^2/r^2 = (6.67 × 10^{-11})(1.673 × 10^{-27})^2/(1.3 × 10^{-15})^2.', 'F_G = <b>1.1 × 10^{-34} N</b>, attractive.', 'Using unrounded forces, F_E/F_G = 1.23554 × 10^{36} ≈ <b>1.24 × 10^{36}</b>.', 'Gravity is far too weak to account for nuclear binding.']) },
  { id: 'p8ns06', dp: '8.4.1', t: 'con', q: 'What properties allow the strong nuclear force to bind nucleons?', a: L(['It acts between <b>all nucleons</b>, regardless of electric charge.', 'It is strongly attractive at typical nucleon separations and has a <b>very short range</b> of a few femtometres.', 'At extremely small separations it becomes repulsive, preventing unlimited compression.']) },
  { id: 'p8ns07', dp: '8.4.1', t: 'exam', q: '2011 HSC (3 marks; Quanta to Quarks): Compare the strength, direction and range of gravitational, electrostatic and strong forces in the nucleus.', a: L(['<b>Gravity:</b> weakest; attractive; infinite range.', '<b>Electrostatic force between protons:</b> stronger than gravity; repulsive; infinite range.', '<b>Strong nuclear force:</b> strongest at typical nucleon spacing; attractive there; short range.']) + N('Strong attraction applies at binding distances; extremely close nucleons repel.'), v: 'nuclearForces' },
  { id: 'p8ns08', dp: '8.4.1', t: 'con', q: 'Why do larger stable nuclei generally need more neutrons than protons?', a: L(['Additional protons increase <b>long-range electrostatic repulsion</b>.', 'Neutrons contribute attractive strong interactions without adding electric repulsion.', 'Light stable nuclei usually have N/Z near 1; heavier stable nuclei generally require a larger ratio.']) + N('The source initially says neutrons supply only gravity. They also participate in strong nuclear binding.') },
  { id: 'p8ns09', dp: '8.4.1', t: 'con', q: 'How does position relative to the band of stability suggest a decay mode?', a: L(['<b>Too many neutrons:</b> beta-minus decay converts a neutron to a proton.', '<b>Too few neutrons:</b> beta-plus decay or electron capture converts a proton to a neutron.', '<b>Very heavy nuclei:</b> alpha decay often reduces nuclear size.', 'These are trends, not rules that determine every isotope’s decay.']) + N('Heavy nuclei do not all decay by alpha emission; the source’s Th-233 example beta-decays.') },
  { id: 'p8ns10', dp: '8.4.1', t: 'con', q: 'How do odd/even nucleon numbers and magic numbers help predict stability?', a: L(['Even numbers of both protons and neutrons are generally associated with greater stability.', '<b>Magic numbers</b> correspond to filled nuclear shells and can enhance stability.', 'Neither observation guarantees that an isotope is stable.']) + N('Magic-number lists conflict; filled shells can enhance stability but never guarantee it.') },
  { id: 'p8ns11', dp: '8.4.1', t: 'def', q: 'What distinguishes a stable isotope from a radioactive isotope?', a: L(['A <b>radioactive isotope</b> undergoes spontaneous nuclear decay.', 'A stable isotope does not undergo the radioactive decay being considered.', 'For example, carbon-12 is stable while carbon-14 undergoes beta-minus decay.']) + N('Seeking lowest energy is not a definition of entropy. Allowed decay products and conservation laws matter.') },
]});
DECKS.push({ id: 'phys-m8-rd', fa: 'fa4', title: 'Radioactive emissions and decay equations', dps: ['8.4.1', '8.4.4'], cards: [
  { id: 'p8rd01', dp: '8.4.1', t: 'def', q: 'What is spontaneous radioactive decay?', a: L(['An <b>unstable nucleus</b> changes without external triggering and releases radiation.', 'Individual decay is random with constant probability per unit time; large populations show predictable exponential decay.']) },
  { id: 'p8rd02', dp: '8.4.1', t: 'rec', q: 'What are the nature, charge and penetration of alpha radiation?', a: L(['<b>Helium-4 nuclei:</b> two protons and two neutrons; charge +2e.', '<b>Strongly ionising</b>, with low penetration.', 'Stopped by paper or a short distance in air.']) },
  { id: 'p8rd03', dp: '8.4.1', t: 'rec', q: 'What are the nature, charge and penetration of beta radiation?', a: L(['<b>Beta-minus:</b> electrons with charge −e; <b>beta-plus:</b> positrons with charge +e.', 'Both have electron mass and are emitted in nuclear processes.', 'Generally less ionising and more penetrating than alpha radiation; a thin aluminium barrier can stop them.']) },
  { id: 'p8rd04', dp: '8.4.1', t: 'rec', q: 'What are the nature, charge and penetration of gamma radiation?', a: L(['High-energy <b>electromagnetic photons</b> with zero charge and zero rest mass.', 'Weakly ionising compared with alpha and beta radiation; highly penetrating.', 'Thick lead or concrete <b>attenuates</b> gamma radiation.']) + N('Gamma rays are photons. Shielding attenuates intensity rather than guaranteeing complete absorption.') },
  { id: 'p8rd05', dp: '8.4.1', t: 'prac', q: 'Radiation moves right through a magnetic field into the page. Which paths identify alpha, beta-minus and gamma radiation?', a: L(['<b>Alpha:</b> curves upwards because its positive charge experiences an upward magnetic force.', '<b>Beta-minus:</b> curves downwards because its negative charge reverses the force.', '<b>Gamma:</b> continues straight because it has no electric charge.', 'Use F = |q|vB and force direction to infer charge; radius r = p/(|q|B) explains tighter curvature for lower momentum per charge.']) },
  { id: 'p8rd07', dp: '8.4.1', t: 'exam', q: '2015 HSC (2 marks; booklet label NESA): How could a Wilson cloud chamber distinguish polonium-218 alpha and beta decays?', a: L(['Radiation <b>ionises</b> gas; condensation along the ionised path makes a track visible.', 'Alpha particles produce <b>short, thick tracks</b> from stronger ionisation.', 'Beta particles produce <b>longer, thinner tracks</b>; a magnetic field can also distinguish charge through opposite curvature.']) },
  { id: 'p8rd09', dp: '8.4.4', t: 'eq', q: 'How does alpha decay change A and Z? Give the uranium-238 example.', a: L(['The daughter has <b>A reduced by 4</b> and <b>Z reduced by 2</b>.']) + E('^{238}_{92}U → ^{234}_{90}Th + ^4_2He') },
  { id: 'p8rd10', dp: '8.4.4', t: 'eq', q: 'What changes occur in beta-minus decay? Give the thorium-234 example.', a: L(['A neutron becomes a proton, an electron and an <b>electron antineutrino</b>.', '<b>A stays constant; Z increases by 1</b>.']) + E('n → p + e^- + ν̄_e') + E('^{234}_{90}Th → ^{234}_{91}Pa + ^0_{−1}e + ν̄_e') },
  { id: 'p8rd11', dp: '8.4.4', t: 'eq', q: 'What changes occur in beta-plus decay? Give the carbon-10 example.', a: L(['A proton in the nucleus becomes a neutron, a positron and an <b>electron neutrino</b>.', '<b>A stays constant; Z decreases by 1</b>.']) + E('p → n + e^+ + ν_e') + E('^{10}_6C → ^{10}_5B + ^0_{+1}e + ν_e') },
  { id: 'p8rd12', dp: '8.4.4', t: 'eq', q: 'How does gamma emission affect isotope identity? Give the technetium-99m example.', a: L(['An excited nucleus releases energy as a <b>gamma photon</b>.', '<b>A and Z stay constant</b>; the element does not change.']) + E('^{99m}_{43}Tc → ^{99}_{43}Tc + γ') + N('Gamma emission does not change the element; not every decay is an elemental transmutation.') },
  { id: 'p8rd13', dp: '8.4.4', t: 'calc', q: 'How many alpha and beta-minus decays convert uranium-238 to lead-206?', a: OL(['Each alpha decay reduces A by 4: (238 − 206)/4 = <b>8 alpha decays</b>.', 'After these, Z = 92 − 2(8) = 76.', 'Each beta-minus decay increases Z by 1: 82 − 76 = <b>6 beta-minus decays</b>.']) },
  { id: 'p8rd14', dp: '8.4.4', t: 'con', q: 'How did Pauli explain the continuous energy distribution of beta-minus electrons?', a: L(['Beta electrons showed a <b>continuous energy spectrum</b>, suggesting missing energy.', 'Pauli proposed a neutral particle sharing the decay energy.', 'The electron, antineutrino and daughter recoil conserve total energy and momentum.']) + N('For beta-minus decay the particle is an antineutrino; daughter recoil also carries energy.') },
]});
DECKS.push({ id: 'phys-m8-hl', fa: 'fa4', title: 'Half-life model and activity investigations', dps: ['8.4.2'], cards: [
  { id: 'p8hl01', dp: '8.4.2', t: 'def', q: 'What is the half-life of a radioactive isotope?', a: L(['The time for <b>half the remaining radioactive nuclei</b> to decay.', 'The amount and activity halve during each successive half-life.']) },
  { id: 'p8hl03', dp: '8.4.2', t: 'eq', q: 'Which equations predict the amount remaining after time t?', a: E('N_t = N_0e^{−λt} = N_0(1/2)^{t/t_{1/2}}') + L(['<b>N_0:</b> initial number; <b>N_t:</b> number remaining.', '<b>λ:</b> decay constant; <b>t_{1/2}:</b> half-life.', 'The same remaining fraction applies to isotope mass and activity.', 'Use consistent time units for t, half-life and λ.']) },
  { id: 'p8hl04', dp: '8.4.2', t: 'eq', q: 'How is the decay constant related to half-life?', a: OL(['At t = t_{1/2}, N_t/N_0 = 1/2 = e^{−λt_{1/2}}.', 'Taking natural logarithms gives ln(2) = λt_{1/2}.']) + E('λ = ln(2)/t_{1/2}') + L(['λ has inverse-time units, such as <b>s^{-1}</b> or day^{-1}.']) },
  { id: 'p8hl05', dp: '8.4.2', t: 'def', q: 'What is radioactive activity and how does it depend on the amount remaining?', a: L(['<b>Activity</b> is the number of decays per unit time.', 'A = λN, so the activity falls as the number of undecayed nuclei falls.', 'One <b>becquerel</b> is one decay per second; measured detector counts are not automatically equal to total decays.']) },
  { id: 'p8hl06', dp: '8.4.2', t: 'prac', q: 'How would you estimate half-life graphically from the booklet’s activity data?', a: OL(['Plot <b>time in seconds</b> horizontally and <b>activity in counts per second</b> vertically.', 'Draw a smooth decay trend through the fluctuating measurements.', 'Read times for the trend to fall from about 255 to 128, then to 64 counts per second.', 'Average the successive halving intervals: approximately <b>0.33 s</b>.']) + N('OCR lost decimals: times are 0.0–1.4 s. The rise at 0.7 s is retained as measured.'), vf: 'activityData' },
  { id: 'p8hl07', dp: '8.4.2', t: 'calc', q: 'A detector count rate falls from 600 to 100 counts per minute in 6 hours. Estimate λ and half-life.', a: OL(['100/600 = e^{−6λ}.', 'λ = ln(6)/6 = 0.2986266 h^{-1} ≈ <b>0.30 h^{-1}</b>.', 't_{1/2} = ln(2)/λ = 2.32112 h ≈ <b>2.3 h</b>.']) },
  { id: 'p8hl08', dp: '8.4.2', t: 'con', q: 'Does a sample completely decay after ten half-lives?', a: L(['The model gives a remaining fraction of (1/2)^{10} = 1/1024.', 'Approximately <b>0.0977%</b> remains; approximately 99.9023% has decayed.', 'For fermium-253 with half-life 0.334 s, ten half-lives take <b>3.34 s</b>.']) + N('Source treats ten half-lives as complete decay; 0.0977% remains in the model.') },
]});
DECKS.push({ id: 'phys-m8-hc', fa: 'fa4', title: 'Quantitative half-life problems', dps: ['8.4.2'], cards: [
  { id: 'p8hc01', dp: '8.4.2', t: 'calc', q: 'A 128 g radon-212 sample has half-life 23 min. What remains after 23 min, 46 min and 1 hour?', a: OL(['After 23 min: 128(1/2) = <b>64 g</b>.', 'After 46 min: 128(1/2)^2 = <b>32 g</b>.', 'For 1 hour, t = 60 min: m = 128(1/2)^{60/23} = 20.98526 g ≈ <b>21 g</b>.']) },
  { id: 'p8hc02', dp: '8.4.2', t: 'calc', q: 'Iodine-131 has half-life 8.040 days. How long does 60.0 g take to decrease to 0.4 g?', a: OL(['m/m_0 = 0.4/60.0 = (1/2)^{t/8.040}.', 't = 8.040 ln(60.0/0.4)/ln(2) = 58.1197 days.', 'Report approximately <b>58 days</b>; the target mass limits precision.']) },
  { id: 'p8hc04', dp: '8.4.2', t: 'calc', q: 'How much of an initial 150.0 g osmium sample has decayed after five half-lives?', a: OL(['m_{remaining} = 150.0(1/2)^5 = 4.6875 g.', 'm_{decayed} = 150.0 − 4.6875 = 145.3125 g.', 'To the initial mass’s decimal precision: <b>145.3 g has decayed</b>.']) },
  { id: 'p8hc06', dp: '8.4.2', t: 'calc', q: 'Uranium-238 has half-life 4.46 × 10^9 years. What remains of 6.0 g after 2.5 × 10^9 years?', a: OL(['m = 6.0(1/2)^{(2.5 × 10^9)/(4.46 × 10^9)}.', 'm = 4.068295 g ≈ <b>4.1 g</b> to two significant figures.']) },
  { id: 'p8hc09', dp: '8.4.2', t: 'calc', q: 'Strontium-90 has half-life 28.1 years and initial count rate 400 counts s^{-1}. What is the rate after 92 years?', a: OL(['R = R_0(1/2)^{t/t_{1/2}}.', 'R = 400(1/2)^{92/28.1} = 41.35056 counts s^{-1}.', 'Approximately <b>41 counts s^{-1}</b>, using two significant figures for the elapsed time.']) },
  { id: 'p8hc11', dp: '8.4.2', t: 'calc', q: 'Palladium-100 has half-life 3.6 days. How many of an initial 6.02 × 10^{23} atoms remain after 30 days?', a: OL(['N = (6.02 × 10^{23})(1/2)^{30/3.6}.', 'N = 1.8664364 × 10^{21} atoms ≈ <b>1.9 × 10^{21} atoms</b>.']) },
]});
DECKS.push({ id: 'phys-m8-fi', fa: 'fa4', title: 'Discovery of fission and chain reactions', dps: ['8.4.3', '8.4.4'], cards: [
  { id: 'p8fi02', dp: '8.4.3', t: 'con', q: 'Why are neutrons useful projectiles for inducing nuclear reactions?', a: L(['They have <b>no electric charge</b>, so the positive nucleus does not electrostatically repel them.', 'A neutron can enter and be absorbed by a nucleus.', 'Their mass is similar to a proton’s, but their lack of charge prevents direct acceleration by an electric field.']) },
  { id: 'p8fi03', dp: '8.4.3', t: 'rec', q: 'How did Fermi, Hahn, Strassmann, Meitner and Frisch contribute to understanding fission?', a: L(['<b>Fermi:</b> bombarded uranium with neutrons and initially interpreted products as heavier elements.', '<b>Hahn and Strassmann:</b> identified lighter products, including barium.', '<b>Meitner and Frisch:</b> explained the results as splitting of the nucleus, or nuclear fission.']) },
  { id: 'p8fi04', dp: '8.4.4', t: 'eq', q: 'Write and balance the booklet’s uranium-235 fission reaction producing barium and krypton.', a: E('^{235}_{92}U + ^1_0n → ^{236}_{92}U* → ^{141}_{56}Ba + ^{92}_{36}Kr + 3^1_0n') + L(['<b>Mass numbers:</b> 235 + 1 = 141 + 92 + 3 = 236.', '<b>Charge:</b> 92 = 56 + 36.']) + N('Mass number is conserved; rest mass need not be. Total mass-energy is conserved.') },
  { id: 'p8fi05', dp: '8.4.3', t: 'con', q: 'How do neutrons released by fission create a chain reaction?', a: L(['An incident neutron triggers fission of a fissile nucleus.', 'Fission releases additional neutrons.', 'Some strike other fissile nuclei and produce further fissions, repeating the process.']) },
  { id: 'p8fi06', dp: '8.4.3', t: 'con', q: 'What distinguishes a controlled from an uncontrolled fission chain reaction?', a: L(['<b>Controlled:</b> on average, one neutron from each fission causes one subsequent fission; power stays steady.', '<b>Uncontrolled:</b> on average, more than one causes a subsequent fission; the reaction rate and power grow rapidly.']) },
  { id: 'p8fi07', dp: '8.4.3', t: 'def', q: 'What is critical mass and why does a subcritical arrangement fail to sustain a chain reaction?', a: L(['<b>Critical mass</b> is the minimum amount of fissile material needed to sustain the chain reaction for the stated arrangement.', 'Too many neutrons escape or are absorbed without causing fission in a subcritical arrangement.', 'The rate falls when fewer than one subsequent fission occurs per fission on average.']) + N('Subcritical material can still undergo induced fission; this is not merely natural radioactive decay.') },
  { id: 'p8fi08', dp: '8.4.3', t: 'exam', q: '2012 HSC (3 marks; booklet label NESA): What are the requirements for an uncontrolled nuclear chain reaction?', a: L(['A sufficient <b>concentration and arrangement of fissile material</b>, such as uranium-235 or plutonium-239.', 'Neutrons initiate fission and further neutrons are released.', 'Enough of these cause new fissions for <b>more than one subsequent fission per fission</b> on average, producing rapid growth.']) },
]});
DECKS.push({ id: 'phys-m8-re', fa: 'fa4', title: 'Controlled reactors and their components', dps: ['8.4.3', '8.4.4'], cards: [
  { id: 'p8re01', dp: '8.4.3', t: 'rec', q: 'How did Fermi’s 1942 experiment demonstrate controlled fission?', a: L(['Uranium supplied fissile nuclei; <b>graphite</b> slowed neutrons.', '<b>Cadmium control rods</b> absorbed neutrons to regulate the chain reaction.', 'The first controlled reactor demonstrated a self-sustaining reaction at low power.']) },
  { id: 'p8re02', dp: '8.4.3', t: 'con', q: 'What does enrichment change in uranium fuel?', a: L(['It increases the <b>proportion of uranium-235</b> relative to natural uranium.', 'This raises the probability that a neutron will cause the desired fission.', 'Natural uranium contains only a small proportion of uranium-235.']) + N('U-238 is radioactive. Natural uranium can sustain fission in a suitable reactor, as Fermi’s example shows.') },
  { id: 'p8re03', dp: '8.4.3', t: 'con', q: 'What does the moderator do, and which materials does the booklet support?', a: L(['<b>Slows neutrons</b> through collisions, increasing their probability of inducing uranium-235 fission in a thermal reactor.', 'Examples are <b>water, heavy water and graphite</b>.']) + N('Air and helium belong to coolant examples here. Not all fission needs slow neutrons.') },
  { id: 'p8re04', dp: '8.4.3', t: 'con', q: 'How do control rods regulate reactor power?', a: L(['Materials such as <b>boron or cadmium absorb neutrons</b>.', 'Inserting rods removes more neutrons and reduces the fission rate.', 'Withdrawing rods allows more neutrons to cause fission; full insertion can stop the chain reaction.']) },
  { id: 'p8re05', dp: '8.4.3', t: 'con', q: 'How do coolant and radiation shielding serve different reactor functions?', a: L(['<b>Coolant:</b> removes fuel heat for steam → turbine → generator: thermal → mechanical → electrical energy.', '<b>Shielding:</b> thick protective material absorbs or attenuates escaping radiation to protect people and the environment.']) + N('Neutron reflection and radiation shielding have different functions.') },
  { id: 'p8re07', dp: '8.4.4', t: 'exam', q: '2017 HSC (2 marks; booklet label NESA): Distinguish nuclear fission from transmutation.', a: L(['<b>Fission:</b> a heavy nucleus splits into smaller nuclei.', '<b>Transmutation:</b> a nucleus changes into a different element, so Z changes.', 'Fission is one type of transmutation; other types include alpha and beta decay.']) },
  { id: 'p8re08', dp: '8.4.3', t: 'exam', q: '2017 HSC (3 marks; booklet label NESA): Explain how fuel, moderator and control rods work together to produce a controlled reaction.', a: L(['<b>Fuel</b> provides fissile nuclei that release neutrons and energy when they split.', 'The <b>moderator</b> slows neutrons so they are more likely to cause further uranium-235 fission.', '<b>Control rods</b> absorb excess neutrons, maintaining about one subsequent fission per fission and steady power.']) },
]});
DECKS.push({ id: 'phys-m8-be', fa: 'fa4', title: 'Mass defect and the binding-energy curve', dps: ['8.4.4', '8.4.5', '8.4.6'], cards: [
  { id: 'p8be01', dp: '8.4.6', t: 'def', q: 'What is nuclear binding energy?', a: L(['The <b>minimum energy required</b> to separate a nucleus completely into its constituent protons and neutrons.', 'It equals the energy released when those separated nucleons form that nucleus.']) },
  { id: 'p8be02', dp: '8.4.6', t: 'eq', q: 'How are mass defect and binding energy calculated using nuclear masses?', a: E('Δm = Zm_p + (A − Z)m_n − m_{nucleus}') + E('E_b = Δmc^2') + L(['The bound nucleus has <b>less rest mass</b> than its separated nucleons.', 'Use kilograms for Δm to obtain joules.']) + N('Binding lowers nuclear rest mass; the source’s “strong force appears as mass” wording is misleading.') },
  { id: 'p8be03', dp: '8.4.6', t: 'eq', q: 'How do you convert atomic mass units and energy units in a mass-defect calculation?', a: L(['<b>1 u = 1.661 × 10^{-27} kg</b>, using the booklet’s data-sheet value.', '<b>1 eV = 1.602 × 10^{-19} J</b>; 1 MeV = 1.602 × 10^{-13} J.', 'Using the supplied equivalence: <b>Q in MeV = Δm in u × 931.5</b>.']) + N('Use 1.661, not the source’s 1.667 × 10^{-27} kg per u. Rounded conversion routes may differ slightly. Energy-requiring reactions can occur if sufficient incident or thermal energy is supplied.') },
  { id: 'p8be05', dp: '8.4.6', t: 'con', q: 'Describe the overall shape and peak of the binding-energy-per-nucleon curve.', a: L(['Rises steeply for light nuclei.', 'Peaks at about <b>8.8 MeV per nucleon</b> near A ≈ 60, in the iron group.', 'Decreases gradually for heavier nuclei; larger E_b/A generally means tighter binding.', 'The booklet identifies <b>nickel-62</b>, rather than iron-56, as having the highest binding energy per nucleon.']) },
  { id: 'p8be08', dp: '8.4.6', t: 'exam', q: '2014 HSC (3 marks; booklet label NESA): Use the binding-energy-per-nucleon curve to explain energy release in a nuclear reaction.', a: L(['<b>Light nuclei fuse</b> towards the curve’s peak, or <b>heavy nuclei split</b> into more tightly bound products.', 'Products have greater total binding energy and lower combined rest mass.', 'The rest-mass decrease is released as energy according to <b>Q = Δmc^2</b>.']) },
  { id: 'p8be10', dp: '8.4.6', t: 'calc', q: 'Nickel-62 has total binding energy 545.281 MeV. Find the energy per nucleon in MeV and joules.', a: OL(['E_b/A = 545.281/62 = <b>8.79485 MeV per nucleon</b>.', 'Convert with 1 MeV = 1.602 × 10^{-13} J.', '(8.79485484)(1.602 × 10^{-13}) = <b>1.409 × 10^{-12} J per nucleon</b>.']) },
  { id: 'p8be11', dp: '8.4.6', t: 'calc', q: 'Find tritium’s binding energy using M = 3.016049 u, m_p = 1.007276 u, m_n = 1.008665 u and m_e = 0.000549 u.', a: OL(['The tabulated 3.016049 u is an <b>atomic mass</b>; compare with one proton, two neutrons and one electron.', 'Separated mass = 1.007276 + 2(1.008665) + 0.000549 = 3.025155 u.', 'Δm = 3.025155 − 3.016049 = 0.009106 u.', 'E_b = 0.009106 × 931.5 = <b>8.482 MeV</b>.', 'E_b/A = 8.482239/3 = <b>2.827 MeV per nucleon</b>.']) + N('3.016049 u is atomic mass, despite the “nucleus” label; electron accounting corrects the key’s approximately 7.97 MeV.') },
  { id: 'p8be12', dp: '8.4.4', t: 'exam', q: '2012 HSC (3 marks; booklet label NESA): How does mass-energy equivalence explain natural radioactivity?', a: L(['The parent’s rest energy exceeds that of the allowed decay products.', 'The <b>rest-mass decrease</b> supplies kinetic energy of emitted particles and the recoiling daughter, and any radiation.', '<b>Total mass-energy is conserved</b>, with Q = (m_{parent} − m_{products})c^2.']) },
]});
DECKS.push({ id: 'phys-m8-ne', fa: 'fa4', title: 'Nuclear reaction energies and fusion conditions', dps: ['8.4.4', '8.4.5', '8.4.6'], cards: [
  { id: 'p8ne02', dp: '8.4.6', t: 'calc', q: 'Beryllium-7 captures an electron to form lithium-7. Using atomic masses 7.016931 u and 7.016005 u, calculate the released energy.', a: OL(['Nuclear process: ^7_4Be + ^0_{−1}e → ^7_3Li + ν_e.', 'Using <b>neutral atomic masses</b>, Δm = 7.016931 − 7.016005 = <b>0.000926 u</b>.', 'Δm = (0.000926)(1.661 × 10^{-27}) = <b>1.538 × 10^{-30} kg</b>.', 'Q = (1.538086 × 10^{-30})(3.00 × 10^8)^2 = <b>1.38 × 10^{-13} J</b>.']) + N('Atomic mass already counts the captured electron; the key double-counts it.') },
  { id: 'p8ne03', dp: '8.4.6', t: 'calc', q: 'Potassium-42 beta-minus decays to calcium-42. Atomic masses are 41.962417 u and 41.958628 u. Find Q in MeV.', a: OL(['^{42}_{19}K → ^{42}_{20}Ca + ^0_{−1}e + ν̄_e.', 'For neutral atomic masses in beta-minus decay, Δm = 41.962417 − 41.958628 = <b>0.003789 u</b>.', 'Q = 0.003789 × 931.5 = <b>3.529 MeV</b>.']) + N('Do not subtract an extra electron from atomic masses; the key’s approximately 3.02 MeV becomes 3.529 MeV.') },
  { id: 'p8ne04', dp: '8.4.4', t: 'eq', q: 'What isotope can neutron activation of deuterium produce, and what follows its beta decay?', a: E('^2_1H + ^1_0n → ^3_1H + γ') + E('^3_1H → ^3_2He + ^0_{−1}e + ν̄_e') + L(['Neutron capture produces <b>tritium</b>.', 'Its beta-minus decay produces <b>helium-3</b>.']) },
  { id: 'p8ne06', dp: '8.4.6', t: 'exam', q: '2015 HSC (3 marks; booklet label NESA): Calculate Q for polonium-218 alpha decay using masses 218.00897 u, 213.99981 u and 4.00260 u.', a: OL(['^{218}_{84}Po → ^{214}_{82}Pb + ^4_2He.', 'Δm = 218.00897 − 213.99981 − 4.00260 = 0.00656 u.', 'Q = 0.00656 × 931.5 = <b>6.11 MeV</b>.', 'Equivalently, using the supplied kg conversion and c: Q = <b>9.81 × 10^{-13} J</b>.']) + N('These are atomic masses, despite their labels; electrons balance in the alpha reaction.') },
  { id: 'p8ne07', dp: '8.4.6', t: 'exam', q: '2013 HSC (3 marks; booklet label NESA): Calculate Q for U-235 + n → Ba-141 + Kr-92 + 3n using masses 235.0439, 1.008665, 140.9144 and 91.92616 u.', a: OL(['Reactants: 235.0439 + 1.008665 = 236.052565 u.', 'Products: 140.9144 + 91.92616 + 3(1.008665) = 235.866555 u.', 'Δm = 236.052565 − 235.866555 = 0.186010 u.', 'Q = 0.186010 × 931.5 = 173.268315 MeV ≈ <b>173.3 MeV</b>.']) + N('The referenced table is incomplete; earlier booklet masses are supplied. Correct Q is 173.3, not 194.86 MeV.') },
  { id: 'p8ne08', dp: '8.4.6', t: 'exam', q: '2013 HSC (2 marks; booklet label NESA): Apply mass-energy equivalence to explain energy production in uranium fission.', a: L(['The products’ <b>combined rest mass is less</b> than that of the uranium nucleus plus incident neutron.', 'The rest-mass decrease becomes released energy according to <b>Q = Δmc^2</b>; total mass-energy is conserved.']) },
  { id: 'p8ne09', dp: '8.4.5', t: 'con', q: 'Why are high temperature and confinement needed for sustained fusion?', a: L(['Positive nuclei experience strong <b>electrostatic repulsion</b>.', 'High temperature supplies large kinetic energies; high density and confinement increase the opportunity for fusion.', 'Stars provide gravitational confinement; laboratory fusion must provide suitable conditions and obtain a useful <b>net energy gain</b>.']) },
  { id: 'p8ne10', dp: '8.4.5', t: 'eq', q: 'What is the deuterium–tritium fusion reaction described in the booklet?', a: E('^2_1H + ^3_1H → ^4_2He + ^1_0n + energy') + L(['The lighter nuclei combine to form more tightly bound products.', 'The rest-mass decrease is released as kinetic energy.', 'The booklet uses this reaction to explain the challenge of laboratory fusion at extremely high temperatures.']) },
]});
DECKS.push({ id: 'phys-m8-pe', fa: 'fa5', title: 'Evidence for particles inside and beyond nucleons', dps: ['8.5.1'], cards: [
  { id: 'p8pe01', dp: '8.5.1', t: 'def', q: 'How do fundamental and composite particles differ?', a: L(['A <b>fundamental particle</b> has no constituent particles in the model.', 'A <b>composite particle</b> contains smaller particles.', 'Electrons and quarks are fundamental in the Standard Model; protons and neutrons contain quarks.']) },
  { id: 'p8pe02', dp: '8.5.1', t: 'prac', q: 'How did cosmic-ray cloud-chamber observations reveal new charged particles?', a: L(['Energetic cosmic-ray interactions produced particle tracks in a cloud chamber.', 'A magnetic field curved charged tracks; curvature direction revealed the <b>sign of charge</b>.', 'Track characteristics and curvature showed particles with properties different from known electrons and protons.']) },
  { id: 'p8pe03', dp: '8.5.1', t: 'con', q: 'What evidence identified the positron as the electron’s antiparticle?', a: L(['It had the <b>same mass</b> as an electron and the <b>opposite charge</b>.', 'Its track curved oppositely to an electron track under comparable magnetic conditions.', 'Electron–positron annihilation converted their rest mass to radiation.']) },
  { id: 'p8pe04', dp: '8.5.1', t: 'con', q: 'How did muon observations challenge a model containing only electrons, protons and neutrons?', a: L(['Cosmic-ray observations revealed a charged particle with properties distinct from those three particles.', 'The <b>muon</b> is heavier than an electron and belongs to the lepton family.', 'A broader model of subatomic matter was therefore required.']) + N('Muons are leptons, not hadrons as implied by the source.') },
  { id: 'p8pe06', dp: '8.5.1', t: 'con', q: 'Why does the neutron’s magnetic moment suggest internal structure?', a: L(['The neutron has <b>zero net electric charge</b> but a magnetic moment.', 'Internal charged constituents can have cancelling net charge while producing magnetic behaviour.', 'This supports a composite neutron with charged quarks.']) },
  { id: 'p8pe07', dp: '8.5.1', t: 'exam', q: '2019 HSC (5 marks; Q32): Describe experiments that increased understanding of the electron and one other fundamental particle.', a: L(['<b>Electron:</b> Millikan observed charged oil drops under gravity and an electric field.', 'Measured forces allowed drop charges to be calculated; the charges were integer multiples of a smallest value, establishing the <b>elementary charge</b>.', '<b>Quarks:</b> high-energy electrons were scattered from nucleons at SLAC.', 'The scattering indicated smaller internal constituents rather than featureless protons and neutrons.', 'Together, the experiments established a property of the electron and evidence that nucleons have <b>quark structure</b>.']) },
]});
DECKS.push({ id: 'phys-m8-sm', fa: 'fa5', title: 'Standard Model particles and interactions', dps: ['8.5.2'], cards: [
  { id: 'p8sm01', dp: '8.5.2', t: 'rec', q: 'What are the six quark flavours and their charges?', a: L(['<b>Up, charm, top:</b> charge +2e/3.', '<b>Down, strange, bottom:</b> charge −e/3.', 'Each has a corresponding antiquark with the opposite electric charge.']) + N('Quark flavour and strong-interaction colour are different properties.') },
  { id: 'p8sm02', dp: '8.5.2', t: 'rec', q: 'What are the six leptons listed in the Standard Model?', a: L(['<b>Electron, muon and tau</b>, each with charge −e.', '<b>Electron neutrino, muon neutrino and tau neutrino</b>, each electrically neutral.', 'Leptons do not participate in the <b>strong interaction</b>; each has a corresponding antiparticle.']) },
  { id: 'p8sm03', dp: '8.5.2', t: 'def', q: 'How do baryons and mesons differ?', a: L(['Both are <b>hadrons</b>, composed of quarks and affected by the strong interaction.', '<b>Baryon:</b> three quarks, such as a proton or neutron.', '<b>Meson:</b> a quark and an antiquark, such as a pion.']) },
  { id: 'p8sm04', dp: '8.5.2', t: 'calc', q: 'Use quark charges to explain the charges of protons and neutrons.', a: L(['<b>Proton:</b> uud; +2e/3 + 2e/3 − e/3 = <b>+e</b>.', '<b>Neutron:</b> udd; +2e/3 − e/3 − e/3 = <b>0</b>.']) },
  { id: 'p8sm05', dp: '8.5.2', t: 'con', q: 'How do fermions and bosons differ, and which groups are examples?', a: L(['<b>Fermions:</b> half-integer spin; quarks and leptons are fundamental examples.', '<b>Bosons:</b> integer spin; force-carrier particles are examples.', 'Baryons are composite fermions; mesons are composite bosons.']) + N('Mesons are bosons; W/Z bosons are massive. The key’s blanket classifications are incorrect.') },
  { id: 'p8sm06', dp: '8.5.2', t: 'rec', q: 'Which particles mediate the interactions included in the Standard Model?', a: L(['<b>Electromagnetic:</b> photons; acts on electric charge.', '<b>Strong:</b> gluons; binds quarks into hadrons.', '<b>Weak:</b> W^+, W^- and Z bosons; enables processes such as beta decay.', 'Gravity is not incorporated into the Standard Model.']), v: 'interactions' },
  { id: 'p8sm07', dp: '8.5.2', t: 'eq', q: 'How does the quark model explain beta-minus decay?', a: L(['A neutron, <b>udd</b>, becomes a proton, <b>uud</b>, when a down quark becomes an up quark.', 'The weak interaction creates an electron and an electron antineutrino.', 'The electron is <b>produced in the decay</b>; it was not stored inside the nucleus.']) + E('d → u + W^-; W^- → e^- + ν̄_e') + N('The prose says W^+ but the diagram shows W^-; charge conservation requires W^-.') },
  { id: 'p8sm09', dp: '8.5.2', t: 'rec', q: 'Which unresolved questions in the booklet show that understanding of matter is incomplete?', a: L(['How to incorporate <b>gravity</b> consistently with the other interactions.', 'The nature of <b>dark matter and dark energy</b>.', 'Why the observed Universe contains much more matter than antimatter.', 'Whether proposed unifying theories such as supersymmetry are correct; a graviton remains hypothetical.']) },
]});
DECKS.push({ id: 'phys-m8-ac', fa: 'fa5', title: 'Particle accelerators: operation and evidence', dps: ['8.5.3'], cards: [
  { id: 'p8ac01', dp: '8.5.3', t: 'con', q: 'How does an electron gun produce an accelerated electron beam?', a: L(['A heated cathode emits electrons.', 'The cathode–anode potential difference creates an <b>electric field</b>: E = V/d.', 'The field exerts F = qE, accelerating electrons towards the positive anode.', 'Electrons passing through an anode opening form the beam; the energy gained is |q|V.']) },
  { id: 'p8ac02', dp: '8.5.3', t: 'con', q: 'Where and how does a drift-tube linear accelerator increase particle speed?', a: L(['<b>Electric fields in the gaps</b> exert a force on charged particles.', 'The alternating supply changes polarity so the next gap accelerates the particle forward.', 'Inside conducting drift tubes, particles are shielded from the accelerating field and move at approximately constant speed.']) + N('Particles accelerate across gaps, not inside the shielded drift tubes.') },
  { id: 'p8ac03', dp: '8.5.3', t: 'con', q: 'Why do drift tubes become longer as a non-relativistic particle accelerates?', a: L(['The voltage reverses after a fixed time interval.', 'A faster particle travels farther in that interval: <b>d = vt</b>.', 'Increasing tube lengths keep it shielded during the unsuitable field direction and synchronised with the next accelerating gap.']) },
  { id: 'p8ac04', dp: '8.5.3', t: 'con', q: 'What roles do electric and magnetic fields have in a cyclotron?', a: L(['An alternating <b>electric field</b> accelerates particles across the gap between the dees.', 'A perpendicular <b>magnetic field</b> bends the path without directly increasing speed.', 'As momentum rises, the orbit radius increases and the path spirals outwards.']) },
  { id: 'p8ac05', dp: '8.5.3', t: 'eq', q: 'Why must the bending magnetic field increase as particle momentum rises in a fixed-radius synchrotron?', a: E('r = p/(|q|B)') + L(['<b>Electric accelerating sections</b> increase momentum.', 'Increasing B in proportion to p maintains a fixed r.', 'At low speeds p = mv; at relativistic speeds use p = m_0v/√(1 − v^2/c^2).']) + N('Synchrotrons use ring magnets and accelerating cavities, not cyclotron-style D-shaped chambers.') },
  { id: 'p8ac06', dp: '8.5.3', t: 'con', q: 'Why do superconducting magnets and high vacuum improve accelerator operation?', a: L(['Below their critical temperature, <b>superconductors</b> have zero electrical resistance.', 'Large magnet currents provide stronger bending fields for more energetic charged particles.', '<b>High vacuum</b> reduces unwanted beam collisions with gas molecules.', 'Cooling is still required to maintain superconductivity.']) },
  { id: 'p8ac07', dp: '8.5.3', t: 'rec', q: 'What are the roles of the LHC’s collider, detectors and computing system?', a: L(['<b>Collider:</b> guides opposite-moving high-energy hadron beams into collisions.', '<b>Detectors:</b> measure the resulting particles and radiation.', '<b>Computing system:</b> processes the recorded data to identify collision products and test predictions.']) },
  { id: 'p8ac09', dp: '8.5.3', t: 'exam', q: '2012 HSC (marks not supplied; part d(ii)): How are accelerators used to investigate the structure of matter?', a: L(['<b>Electric fields</b> accelerate charged particles to high kinetic energies; magnetic fields can guide the beams.', 'Particles collide with a target or another beam.', 'Detectors measure scattering, new particles and decay products.', 'Analysis reveals internal structure and tests models; SLAC electron scattering supplied evidence for quarks inside nucleons.']) + N('The booklet does not supply the mark allocation.') },
]});
DECKS.push({ id: 'phys-m8-se', fa: 'fa5', title: 'HSC synthesis: the Standard Model and new questions', dps: ['8.5.1', '8.5.2', '8.5.3'], cards: [
  { id: 'p8se01', dp: '8.5.2', t: 'exam', q: '2004 HSC (2 marks; Q31(b)(i)): State the quark composition of a neutron and a negative pion.', a: L(['<b>Neutron:</b> udd, one up and two down quarks.', '<b>Negative pion:</b> d anti-u, one down quark and one up antiquark.', 'Its charge is −e/3 − 2e/3 = −e.']) },
  { id: 'p8se02', dp: '8.5.3', t: 'exam', q: '2004 HSC (7 marks; Q31(c)): Describe how accelerators developed the Standard Model’s key features and components.', a: L(['Accelerators use <b>electric fields</b> to supply high kinetic energy; magnetic fields guide circular beams.', 'High-energy scattering probes small-scale structure, while collisions can create additional particles.', '<b>SLAC electron scattering</b> showed internal constituents in nucleons, supporting quarks.', 'Measurements of charges, masses, tracks and decay products allowed particles to be identified and classified.', 'The model organises six quark flavours and six leptons, with corresponding antiparticles.', 'Interactions are mediated by photons, gluons and W/Z bosons; accelerator evidence tests these predictions.']) + N('The LHC postdates the 2004 exam; use the earlier SLAC evidence instead.') },
  { id: 'p8se03', dp: '8.5.2', t: 'exam', q: '2008 HSC (4 marks; Q31(d)(ii)): Describe the Standard Model’s key features and components.', a: L(['Fundamental matter particles are <b>quarks and leptons</b>, with six of each and corresponding antiparticles.', 'Quarks form hadrons: three-quark baryons and quark–antiquark mesons.', 'The <b>electromagnetic, strong and weak interactions</b> are mediated by photons, gluons and W/Z bosons respectively.', 'Gravity is outside the Standard Model.']) },
  { id: 'p8se04', dp: '8.5.3', t: 'exam', q: '2009 HSC (6 marks; Q31(e)): Use the Standard Model to show how theories and experiments increase understanding and generate new questions.', a: L(['New particle observations challenged the earlier electron–proton–neutron description of matter.', '<b>Accelerator scattering</b> supplied evidence for quarks inside nucleons; collisions produced additional particles for classification.', 'The Standard Model organised this evidence into quarks, leptons and interaction-mediating bosons.', 'A theory makes <b>testable predictions</b>; agreement supports it and disagreement identifies a need for revision.', 'Its limitations generate further questions, including how gravity fits with other interactions and why matter dominates over antimatter.', 'Those questions motivate new accelerator experiments and further theoretical development.']) },
  { id: 'p8se05', dp: '8.5.3', t: 'con', q: 'Why does evidence for a predicted particle support a model without proving it complete?', a: L(['A successful prediction shows that the model explains a tested aspect of nature.', 'Other observations and unexplained phenomena may still lie outside its scope.', 'The Higgs mechanism predicted a field and boson; CERN’s 2012 evidence supports it, while gravity and matter–antimatter questions remain.']) + N('The Higgs mechanism belongs to the model, contrary to the source’s blanket statement that it has no account of mass.') },
  { id: 'p8se06', dp: '8.5.3', t: 'con', q: 'Why does the booklet discuss heavy-ion collisions as a way to study the early Universe?', a: L(['High-energy heavy-ion collisions can briefly produce very hot, dense matter.', 'The <b>quark–gluon plasma</b> resembles a state considered in the early-Universe model.', 'Studying the collision products tests ideas about matter under those extreme conditions.']) },
]});
